export const ASSETS: Record<string, string> = {
  "admin/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>InsPhoto Admin</title>\n<style>\n  :root { color-scheme: dark; }\n  * { box-sizing: border-box; }\n  html, body {\n    margin: 0;\n    background: #0b0d10;\n    color: #f4f5f6;\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    min-height: 100vh;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .card {\n    background: #15181c;\n    padding: 32px;\n    border-radius: 16px;\n    width: 360px;\n  }\n  h1 { font-size: 18px; margin: 0 0 4px; }\n  p.hint { color: #9aa1a9; font-size: 12px; margin: 0 0 20px; }\n  label { display: block; font-size: 12px; color: #9aa1a9; margin-bottom: 14px; }\n  input {\n    width: 100%;\n    margin-top: 4px;\n    padding: 10px 12px;\n    border-radius: 8px;\n    border: 1px solid #2a2f36;\n    background: #1e2227;\n    color: #f4f5f6;\n    font-size: 14px;\n  }\n  button {\n    width: 100%;\n    background: #0F766E;\n    color: #fff;\n    border: none;\n    border-radius: 10px;\n    padding: 12px;\n    font-weight: 600;\n    font-size: 14px;\n    cursor: pointer;\n  }\n  #result { margin-top: 16px; font-size: 13px; }\n  #result.error { color: #f87171; }\n  #result.ok { color: #4ade80; }\n  #result a { color: #F59E0B; }\n</style>\n</head>\n<body>\n  <div class=\"card\">\n    <h1>Create an event</h1>\n    <p class=\"hint\">Not a guest/console surface — a one-time bootstrap tool gated by the project's create passcode.</p>\n    <form id=\"form\">\n      <label>Create passcode<input id=\"passcode\" type=\"password\" required /></label>\n      <label>Event slug (e.g. mwta72)<input id=\"slug\" type=\"text\" pattern=\"[a-z0-9][a-z0-9-]{2,39}\" required /></label>\n      <label>Event name<input id=\"name\" type=\"text\" required /></label>\n      <label>Host PIN<input id=\"pin\" type=\"text\" required minlength=\"4\" /></label>\n      <button type=\"submit\">Create event</button>\n    </form>\n    <div id=\"result\"></div>\n  </div>\n\n  <script>\n    function apiPath(p) {\n      const marker = \"/album\";\n      const idx = location.pathname.indexOf(marker);\n      const root = idx === -1 ? \"\" : location.pathname.slice(0, idx + marker.length);\n      return root + p;\n    }\n\n    document.getElementById(\"form\").addEventListener(\"submit\", async (e) => {\n      e.preventDefault();\n      const result = document.getElementById(\"result\");\n      result.className = \"\";\n      result.textContent = \"Creating…\";\n      try {\n        const res = await fetch(apiPath(\"/api/admin/events\"), {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify({\n            passcode: document.getElementById(\"passcode\").value,\n            slug: document.getElementById(\"slug\").value.trim(),\n            name: document.getElementById(\"name\").value.trim(),\n            pin: document.getElementById(\"pin\").value.trim(),\n          }),\n        });\n        const body = await res.json();\n        if (!res.ok) throw new Error(body.error || \"failed\");\n        const guestUrl = `${location.origin}${apiPath(\"/e/\" + body.slug)}`;\n        const hostUrl = `${location.origin}${apiPath(\"/h/\" + body.slug)}`;\n        const ledUrl = `${location.origin}${apiPath(\"/s/\" + body.slug)}`;\n        result.className = \"ok\";\n        result.innerHTML = `Created.<br>Guest: <a href=\"${guestUrl}\">${guestUrl}</a><br>Console: <a href=\"${hostUrl}\">${hostUrl}</a><br>LED: <a href=\"${ledUrl}\">${ledUrl}</a>`;\n      } catch (err) {\n        result.className = \"error\";\n        result.textContent = err.message;\n      }\n    });\n  </script>\n</body>\n</html>\n",
  "console/app.js": "// Console: PIN login, live grid + moderation, LED control, event setup.\n// PRD §7.\n(function () {\n  const POLL_MS = 3000;\n\n  const state = {\n    slug: null,\n    token: null,\n    event: null, // full album_events row, kept live via realtime\n    media: [],\n    focusedIndex: -1,\n    lightboxId: null,\n    pollTimer: null,\n    lastEsc: 0,\n  };\n\n  function tokenKey(slug) {\n    return `insphoto_host_token_${slug}`;\n  }\n\n  function slugFromPath() {\n    const m = location.pathname.match(/\\/h\\/([^/]+)$/);\n    return m ? m[1] : null;\n  }\n\n  function toast(message) {\n    const t = document.getElementById(\"toast\");\n    t.textContent = message;\n    t.hidden = false;\n    clearTimeout(toast._t);\n    toast._t = setTimeout(() => (t.hidden = true), 2200);\n  }\n\n  async function apiFetch(path, opts = {}) {\n    const res = await fetch(window.Insphoto.apiPath(path), {\n      ...opts,\n      headers: {\n        \"content-type\": \"application/json\",\n        authorization: `Bearer ${state.token}`,\n        ...(opts.headers || {}),\n      },\n    });\n    if (res.status === 401) {\n      localStorage.removeItem(tokenKey(state.slug));\n      showLogin(\"Session expired — please sign in again.\");\n      throw new Error(\"unauthorized\");\n    }\n    return res;\n  }\n\n  // ---------- login ----------\n\n  function showLogin(error) {\n    document.getElementById(\"app\").hidden = true;\n    document.getElementById(\"loginScreen\").hidden = false;\n    if (error) {\n      const e = document.getElementById(\"loginError\");\n      e.textContent = error;\n      e.hidden = false;\n    }\n  }\n\n  async function attemptLogin(pin) {\n    const res = await fetch(window.Insphoto.apiPath(\"/api/host/login\"), {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ slug: state.slug, pin }),\n    });\n    if (!res.ok) {\n      const body = await res.json().catch(() => ({}));\n      throw new Error(body.error || \"login failed\");\n    }\n    const body = await res.json();\n    state.token = body.token;\n    state.event = body.event;\n    localStorage.setItem(tokenKey(state.slug), body.token);\n    startApp();\n  }\n\n  function bindLogin() {\n    const input = document.getElementById(\"pinInput\");\n    const btn = document.getElementById(\"loginBtn\");\n    const doLogin = async () => {\n      const pin = input.value.trim();\n      if (!pin) return;\n      btn.disabled = true;\n      document.getElementById(\"loginError\").hidden = true;\n      try {\n        await attemptLogin(pin);\n      } catch (e) {\n        document.getElementById(\"loginError\").textContent = e.message;\n        document.getElementById(\"loginError\").hidden = false;\n      } finally {\n        btn.disabled = false;\n      }\n    };\n    btn.addEventListener(\"click\", doLogin);\n    input.addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Enter\") doLogin();\n    });\n  }\n\n  // ---------- live grid ----------\n\n  function mediaThumbUrl(m) {\n    return window.Insphoto.mediaUrl(m.thumb_path || m.storage_path);\n  }\n\n  function renderGrid() {\n    const grid = document.getElementById(\"grid\");\n    grid.innerHTML = \"\";\n    state.media.forEach((m, i) => {\n      const tile = document.createElement(\"div\");\n      tile.className = \"gtile\" + (i === state.focusedIndex ? \" focused\" : \"\");\n      tile.dataset.id = m.id;\n\n      const img = document.createElement(\"img\");\n      img.src = mediaThumbUrl(m);\n      tile.appendChild(img);\n\n      if (m.status !== \"approved\") {\n        const s = document.createElement(\"span\");\n        s.className = `gstatus ${m.status}`;\n        s.textContent = m.status;\n        tile.appendChild(s);\n      }\n      if (m.featured) {\n        const f = document.createElement(\"span\");\n        f.className = \"gfeatured\";\n        f.textContent = \"★\";\n        tile.appendChild(f);\n      }\n      const meta = document.createElement(\"div\");\n      meta.className = \"gmeta\";\n      meta.textContent = `${m.uploader_name || \"Anonymous\"} · ${window.InsphotoFormat.relativeTime(m.created_at)}`;\n      tile.appendChild(meta);\n\n      tile.addEventListener(\"click\", () => {\n        state.focusedIndex = i;\n        openLightbox(m.id);\n      });\n      grid.appendChild(tile);\n    });\n    document.getElementById(\"hStats\").textContent = `${state.media.length} photos`;\n  }\n\n  async function pollFeed() {\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/feed`);\n      if (!res.ok) return;\n      const body = await res.json();\n      state.media = body.media || [];\n      renderGrid();\n    } catch {\n      /* apiFetch already handled 401 */\n    }\n  }\n\n  function startPolling() {\n    clearInterval(state.pollTimer);\n    state.pollTimer = setInterval(pollFeed, POLL_MS);\n    pollFeed();\n  }\n\n  // ---------- lightbox / moderation ----------\n\n  function openLightbox(id) {\n    const m = state.media.find((x) => x.id === id);\n    if (!m) return;\n    state.lightboxId = id;\n    const box = document.getElementById(\"lightbox\");\n    const mediaEl = document.getElementById(\"lbMedia\");\n    mediaEl.innerHTML = \"\";\n    if (m.kind === \"video\") {\n      const v = document.createElement(\"video\");\n      v.src = window.Insphoto.mediaUrl(m.storage_path);\n      v.controls = true;\n      mediaEl.appendChild(v);\n    } else {\n      const img = document.createElement(\"img\");\n      img.src = window.Insphoto.mediaUrl(m.storage_path);\n      mediaEl.appendChild(img);\n    }\n    document.getElementById(\"lbUploader\").textContent = m.uploader_name || \"Anonymous\";\n    document.getElementById(\"lbTime\").textContent = window.InsphotoFormat.relativeTime(m.created_at);\n    document.getElementById(\"lbLikes\").textContent = window.InsphotoFormat.likeLabel(m.like_count, m.liker_count);\n    document.getElementById(\"lbStatus\").textContent = m.status;\n    box.hidden = false;\n  }\n\n  function closeLightbox() {\n    document.getElementById(\"lightbox\").hidden = true;\n    document.getElementById(\"lbMedia\").innerHTML = \"\";\n    state.lightboxId = null;\n  }\n\n  async function moderate(action) {\n    if (!state.lightboxId) return;\n    try {\n      await apiFetch(`/api/host/${state.slug}/media/${state.lightboxId}/${action}`, { method: \"POST\" });\n      toast(`${action} ok`);\n      if (action === \"delete\" || action === \"hide\") closeLightbox();\n      pollFeed();\n    } catch {\n      /* handled */\n    }\n  }\n\n  // ---------- LED control ----------\n\n  function renderLedTab() {\n    const e = state.event;\n    if (!e) return;\n    document.querySelectorAll(\".scene-btn\").forEach((btn) => {\n      btn.classList.toggle(\"active\", btn.dataset.scene === e.led_scene);\n    });\n    document.getElementById(\"currentScene\").textContent = e.led_scene;\n    document.getElementById(\"holdToggle\").checked = !!e.led_hold;\n    document.getElementById(\"delayInput\").value = e.led_delay_seconds;\n  }\n\n  async function setScene(scene) {\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/settings`, {\n        method: \"POST\",\n        body: JSON.stringify({ led_scene: scene }),\n      });\n      if (res.ok) {\n        state.event.led_scene = scene;\n        renderLedTab();\n      }\n    } catch {\n      /* handled */\n    }\n  }\n\n  async function panic() {\n    await setScene(\"blank\");\n    toast(\"LED blanked\");\n  }\n\n  async function toggleHold(hold) {\n    try {\n      await apiFetch(`/api/host/${state.slug}/settings`, {\n        method: \"POST\",\n        body: JSON.stringify({ led_hold: hold }),\n      });\n      state.event.led_hold = hold;\n    } catch {\n      /* handled */\n    }\n  }\n\n  async function saveDelay() {\n    const seconds = parseInt(document.getElementById(\"delayInput\").value, 10) || 0;\n    try {\n      await apiFetch(`/api/host/${state.slug}/settings`, {\n        method: \"POST\",\n        body: JSON.stringify({ led_delay_seconds: seconds }),\n      });\n      state.event.led_delay_seconds = seconds;\n      toast(\"Delay saved\");\n    } catch {\n      /* handled */\n    }\n  }\n\n  // ---------- event setup ----------\n\n  function guestUrl() {\n    return `${location.origin}${window.Insphoto.apiPath(`/e/${state.slug}`)}`;\n  }\n\n  function renderQr() {\n    const container = document.getElementById(\"qr\");\n    container.innerHTML = \"\";\n    const canvas = document.createElement(\"canvas\");\n    container.appendChild(canvas);\n    window.QRCode.toCanvas(canvas, guestUrl(), { width: 180, margin: 1 });\n    document.getElementById(\"guestLink\").value = guestUrl();\n  }\n\n  function downloadQr() {\n    window.QRCode.toDataURL(guestUrl(), { width: 900, margin: 2 }, (err, dataUrl) => {\n      if (err) return console.error(err);\n      const a = document.createElement(\"a\");\n      a.href = dataUrl;\n      a.download = `${state.slug}-qr.png`;\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n    });\n  }\n\n  async function refreshStats() {\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/stats`);\n      if (!res.ok) return;\n      const s = await res.json();\n      const list = document.getElementById(\"statsList\");\n      list.innerHTML = \"\";\n      const rows = [\n        [\"Photos\", s.photos],\n        [\"Contributors\", s.contributors],\n        [\"Pending review\", s.pending],\n        [\"Storage used\", window.InsphotoFormat.bytesLabel(s.bytes)],\n      ];\n      for (const [label, value] of rows) {\n        const li = document.createElement(\"li\");\n        li.textContent = `${label}: ${value}`;\n        list.appendChild(li);\n      }\n    } catch {\n      /* handled */\n    }\n  }\n\n  function fillSettingsForm() {\n    const e = state.event;\n    document.getElementById(\"tUploadOpen\").checked = e.upload_open;\n    document.getElementById(\"tGalleryPublic\").checked = e.gallery_public;\n    document.getElementById(\"tModeration\").checked = e.moderation;\n    document.getElementById(\"tAllowVideo\").checked = e.allow_video;\n    document.getElementById(\"tAllowGuestDelete\").checked = e.allow_guest_delete;\n    document.getElementById(\"fName\").value = e.name || \"\";\n    document.getElementById(\"fTagline\").value = e.tagline || \"\";\n    document.getElementById(\"fHostName\").value = e.host_name || \"\";\n    document.getElementById(\"fWelcome\").value = e.welcome_message || \"\";\n    document.getElementById(\"fBrandColor\").value = e.brand_color || \"#0F766E\";\n    document.getElementById(\"fAccentColor\").value = e.accent_color || \"#F59E0B\";\n  }\n\n  async function saveSettings() {\n    const patch = {\n      upload_open: document.getElementById(\"tUploadOpen\").checked,\n      gallery_public: document.getElementById(\"tGalleryPublic\").checked,\n      moderation: document.getElementById(\"tModeration\").checked,\n      allow_video: document.getElementById(\"tAllowVideo\").checked,\n      allow_guest_delete: document.getElementById(\"tAllowGuestDelete\").checked,\n      name: document.getElementById(\"fName\").value.trim(),\n      tagline: document.getElementById(\"fTagline\").value.trim(),\n      host_name: document.getElementById(\"fHostName\").value.trim(),\n      welcome_message: document.getElementById(\"fWelcome\").value.trim(),\n      brand_color: document.getElementById(\"fBrandColor\").value,\n      accent_color: document.getElementById(\"fAccentColor\").value,\n    };\n    const status = document.getElementById(\"saveStatus\");\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/settings`, {\n        method: \"POST\",\n        body: JSON.stringify(patch),\n      });\n      if (res.ok) {\n        const body = await res.json();\n        state.event = body.event;\n        status.textContent = \"Saved\";\n        setTimeout(() => (status.textContent = \"\"), 2000);\n        document.getElementById(\"hEventName\").textContent = state.event.name;\n      }\n    } catch {\n      /* handled */\n    }\n  }\n\n  async function exportZip() {\n    toast(\"Preparing download…\");\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/export.zip`);\n      if (!res.ok) throw new Error(\"export failed\");\n      const blob = await res.blob();\n      const a = document.createElement(\"a\");\n      a.href = URL.createObjectURL(blob);\n      a.download = `${state.slug}-album.zip`;\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n    } catch (e) {\n      console.error(e);\n      toast(\"Export failed\");\n    }\n  }\n\n  // ---------- tabs & keyboard ----------\n\n  function switchTab(name) {\n    document.querySelectorAll(\".ctab\").forEach((b) => b.classList.toggle(\"active\", b.dataset.tab === name));\n    document.querySelectorAll(\".ctab-panel\").forEach((p) => p.classList.remove(\"active\"));\n    document.getElementById(`ctab-${name}`).classList.add(\"active\");\n    if (name === \"setup\") {\n      renderQr();\n      refreshStats();\n    }\n  }\n\n  function moveFocus(delta) {\n    if (state.media.length === 0) return;\n    state.focusedIndex = Math.max(0, Math.min(state.media.length - 1, state.focusedIndex + delta));\n    renderGrid();\n    const el = document.querySelector(`.gtile[data-id=\"${state.media[state.focusedIndex].id}\"]`);\n    if (el) el.scrollIntoView({ block: \"nearest\" });\n  }\n\n  function bindKeyboard() {\n    document.addEventListener(\"keydown\", (e) => {\n      const typing = [\"INPUT\", \"TEXTAREA\"].includes(document.activeElement.tagName);\n\n      if (e.key === \"Escape\") {\n        if (!document.getElementById(\"lightbox\").hidden) {\n          closeLightbox();\n          return;\n        }\n        const now = Date.now();\n        if (now - state.lastEsc < 600) {\n          panic();\n          state.lastEsc = 0;\n        } else {\n          state.lastEsc = now;\n        }\n        return;\n      }\n\n      if (typing) return;\n\n      if (!document.getElementById(\"app\").hidden && document.getElementById(\"ctab-grid\").classList.contains(\"active\")) {\n        const cols = Math.max(1, Math.floor(document.getElementById(\"grid\").clientWidth / 148));\n        if (e.key === \"ArrowRight\") moveFocus(1);\n        else if (e.key === \"ArrowLeft\") moveFocus(-1);\n        else if (e.key === \"ArrowDown\") moveFocus(cols);\n        else if (e.key === \"ArrowUp\") moveFocus(-cols);\n        else if (e.key === \"Enter\" && state.focusedIndex >= 0) {\n          openLightbox(state.media[state.focusedIndex].id);\n        }\n      }\n\n      if ([\"1\", \"2\", \"6\"].includes(e.key)) {\n        const map = { 1: \"wall\", 2: \"ranking\", 6: \"blank\" };\n        setScene(map[e.key]);\n      }\n    });\n  }\n\n  function bindStaticUI() {\n    document.querySelectorAll(\".ctab\").forEach((btn) => btn.addEventListener(\"click\", () => switchTab(btn.dataset.tab)));\n    document.getElementById(\"panicBtn\").addEventListener(\"click\", panic);\n    document.getElementById(\"lbClose\").addEventListener(\"click\", closeLightbox);\n    document.getElementById(\"lbApprove\").addEventListener(\"click\", () => moderate(\"approve\"));\n    document.getElementById(\"lbHide\").addEventListener(\"click\", () => moderate(\"hide\"));\n    document.getElementById(\"lbFeature\").addEventListener(\"click\", () => moderate(\"feature\"));\n    document.getElementById(\"lbDelete\").addEventListener(\"click\", () => {\n      if (confirm(\"Permanently delete this photo?\")) moderate(\"delete\");\n    });\n    document.querySelectorAll(\".scene-btn\").forEach((btn) => {\n      btn.addEventListener(\"click\", () => {\n        if (!btn.disabled) setScene(btn.dataset.scene);\n      });\n    });\n    document.getElementById(\"holdToggle\").addEventListener(\"change\", (e) => toggleHold(e.target.checked));\n    document.getElementById(\"delaySave\").addEventListener(\"click\", saveDelay);\n    document.getElementById(\"copyLink\").addEventListener(\"click\", () => {\n      navigator.clipboard.writeText(guestUrl());\n      toast(\"Link copied\");\n    });\n    document.getElementById(\"downloadQr\").addEventListener(\"click\", downloadQr);\n    document.getElementById(\"exportZip\").addEventListener(\"click\", exportZip);\n    document.getElementById(\"saveSettings\").addEventListener(\"click\", saveSettings);\n  }\n\n  function subscribeEventUpdates() {\n    window.Insphoto.supabase\n      .channel(`console-event:${state.event.id}`)\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_events\", filter: `id=eq.${state.event.id}` },\n        (payload) => {\n          state.event = payload.new;\n          renderLedTab();\n        },\n      )\n      .subscribe();\n  }\n\n  function startApp() {\n    document.getElementById(\"loginScreen\").hidden = true;\n    document.getElementById(\"app\").hidden = false;\n    document.getElementById(\"hEventName\").textContent = state.event.name;\n    fillSettingsForm();\n    renderLedTab();\n    subscribeEventUpdates();\n    startPolling();\n  }\n\n  async function tryResumeSession() {\n    const token = localStorage.getItem(tokenKey(state.slug));\n    if (!token) return showLogin();\n    state.token = token;\n    const { data: event, error } = await window.Insphoto.supabase\n      .from(\"album_events\")\n      .select(\"*\")\n      .eq(\"slug\", state.slug)\n      .single();\n    if (error || !event) return showLogin(\"Event not found.\");\n    state.event = event;\n    // Confirm the token still works before showing the app.\n    try {\n      const res = await apiFetch(`/api/host/${state.slug}/feed`);\n      if (!res.ok) return showLogin();\n      startApp();\n    } catch {\n      /* apiFetch already redirected to login on 401 */\n    }\n  }\n\n  function boot() {\n    state.slug = slugFromPath();\n    if (!state.slug) {\n      document.body.innerHTML = \"<p style='padding:40px'>Event not found.</p>\";\n      return;\n    }\n    document.getElementById(\"loginEventName\").textContent = state.slug;\n    bindLogin();\n    bindStaticUI();\n    bindKeyboard();\n    tryResumeSession();\n  }\n\n  document.addEventListener(\"DOMContentLoaded\", boot);\n})();\n",
  "console/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>InsPhoto Console</title>\n<link rel=\"stylesheet\" href=\"./style.css\" />\n</head>\n<body>\n  <div id=\"loginScreen\" class=\"login-screen\">\n    <div class=\"login-card\">\n      <h1>InsPhoto Console</h1>\n      <p id=\"loginEventName\" class=\"muted\"></p>\n      <input id=\"pinInput\" type=\"password\" inputmode=\"numeric\" placeholder=\"Host PIN\" maxlength=\"20\" />\n      <button id=\"loginBtn\">Sign in</button>\n      <p id=\"loginError\" class=\"error\" hidden></p>\n    </div>\n  </div>\n\n  <div id=\"app\" class=\"app\" hidden>\n    <header class=\"cbar\">\n      <div class=\"cbar-left\">\n        <h1 id=\"hEventName\">Console</h1>\n        <span id=\"hStats\" class=\"muted\"></span>\n      </div>\n      <nav class=\"ctabs\">\n        <button class=\"ctab active\" data-tab=\"grid\">Live Grid</button>\n        <button class=\"ctab\" data-tab=\"led\">LED Control</button>\n        <button class=\"ctab\" data-tab=\"setup\">Event Setup</button>\n      </nav>\n      <button id=\"panicBtn\" class=\"panic-btn\">⛔ PANIC</button>\n    </header>\n\n    <main>\n      <section id=\"ctab-grid\" class=\"ctab-panel active\">\n        <div id=\"grid\" class=\"grid\"></div>\n      </section>\n\n      <section id=\"ctab-led\" class=\"ctab-panel\">\n        <div class=\"led-controls\">\n          <div class=\"scene-switch\">\n            <button class=\"scene-btn\" data-scene=\"wall\" data-key=\"1\">1 · Live wall</button>\n            <button class=\"scene-btn\" data-scene=\"ranking\" data-key=\"2\">2 · Ranking</button>\n            <button class=\"scene-btn\" data-scene=\"winner\" data-key=\"3\" disabled>3 · Winner reveal (Sprint 2)</button>\n            <button class=\"scene-btn\" data-scene=\"sponsor\" data-key=\"4\" disabled>4 · Sponsor slate (Sprint 3)</button>\n            <button class=\"scene-btn\" data-scene=\"countdown\" data-key=\"5\" disabled>5 · Countdown (Sprint 2)</button>\n            <button class=\"scene-btn\" data-scene=\"blank\" data-key=\"6\">6 · Blank</button>\n          </div>\n          <div class=\"led-row\">\n            <label><input id=\"holdToggle\" type=\"checkbox\" /> Hold all (pause new photos on LED)</label>\n          </div>\n          <div class=\"led-row\">\n            <label for=\"delayInput\">Delay before a photo can appear on the LED (seconds)</label>\n            <input id=\"delayInput\" type=\"number\" min=\"0\" max=\"600\" />\n            <button id=\"delaySave\">Save</button>\n          </div>\n          <p class=\"muted\">Current scene: <strong id=\"currentScene\">—</strong></p>\n        </div>\n      </section>\n\n      <section id=\"ctab-setup\" class=\"ctab-panel\">\n        <div class=\"setup-grid\">\n          <div class=\"setup-card\">\n            <h2>Guest link</h2>\n            <div id=\"qr\" class=\"qr\"></div>\n            <div class=\"link-row\">\n              <input id=\"guestLink\" readonly />\n              <button id=\"copyLink\">Copy</button>\n            </div>\n            <button id=\"downloadQr\">Download QR (900px PNG)</button>\n          </div>\n\n          <div class=\"setup-card\">\n            <h2>Stats</h2>\n            <ul id=\"statsList\" class=\"stats-list\"></ul>\n            <button id=\"exportZip\">Download album (.zip)</button>\n          </div>\n\n          <div class=\"setup-card\">\n            <h2>Toggles</h2>\n            <label><input type=\"checkbox\" id=\"tUploadOpen\" /> Uploads open</label>\n            <label><input type=\"checkbox\" id=\"tGalleryPublic\" /> Gallery public</label>\n            <label><input type=\"checkbox\" id=\"tModeration\" /> Moderation (review before showing)</label>\n            <label><input type=\"checkbox\" id=\"tAllowVideo\" /> Allow video</label>\n            <label><input type=\"checkbox\" id=\"tAllowGuestDelete\" /> Guests can delete their own upload</label>\n          </div>\n\n          <div class=\"setup-card\">\n            <h2>Branding</h2>\n            <label>Event name<input id=\"fName\" type=\"text\" /></label>\n            <label>Tagline<input id=\"fTagline\" type=\"text\" /></label>\n            <label>Host name<input id=\"fHostName\" type=\"text\" /></label>\n            <label>Welcome / PDPA notice<textarea id=\"fWelcome\" rows=\"3\"></textarea></label>\n            <label>Brand color<input id=\"fBrandColor\" type=\"color\" /></label>\n            <label>Accent color<input id=\"fAccentColor\" type=\"color\" /></label>\n            <button id=\"saveSettings\">Save settings</button>\n            <span id=\"saveStatus\" class=\"muted\"></span>\n          </div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <div id=\"lightbox\" class=\"lightbox\" hidden>\n    <button id=\"lbClose\" class=\"lb-close\">✕</button>\n    <div id=\"lbMedia\" class=\"lb-media\"></div>\n    <div class=\"lb-info\">\n      <span id=\"lbUploader\"></span>\n      <span id=\"lbTime\"></span>\n      <span id=\"lbLikes\"></span>\n      <span id=\"lbStatus\"></span>\n    </div>\n    <div class=\"lb-actions\">\n      <button id=\"lbApprove\">Approve</button>\n      <button id=\"lbHide\">Hide</button>\n      <button id=\"lbFeature\">Feature</button>\n      <button id=\"lbDelete\" class=\"danger\">Delete</button>\n    </div>\n  </div>\n\n  <div id=\"toast\" class=\"toast\" hidden></div>\n\n  <script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js\"></script>\n  <script src=\"../shared/format.js\"></script>\n  <script src=\"../shared/supabase-init.js\"></script>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n",
  "console/style.css": ":root {\n  --brand: #0F766E;\n  --accent: #F59E0B;\n  --bg: #0b0d10;\n  --surface: #15181c;\n  --surface-2: #1e2227;\n  --text: #f4f5f6;\n  --text-dim: #9aa1a9;\n  --danger: #dc2626;\n}\n* { box-sizing: border-box; }\nhtml, body {\n  margin: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n}\nbutton { font-family: inherit; cursor: pointer; }\ninput, textarea { font-family: inherit; }\n.muted { color: var(--text-dim); font-size: 13px; }\n\n.login-screen {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.login-card {\n  background: var(--surface);\n  padding: 32px;\n  border-radius: 16px;\n  width: 320px;\n  text-align: center;\n}\n.login-card h1 { font-size: 18px; margin: 0 0 4px; }\n.login-card input {\n  width: 100%;\n  margin: 16px 0 12px;\n  padding: 12px;\n  border-radius: 10px;\n  border: 1px solid #2a2f36;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 16px;\n  text-align: center;\n}\n.login-card button {\n  width: 100%;\n  background: var(--brand);\n  color: #fff;\n  border: none;\n  border-radius: 10px;\n  padding: 12px;\n  font-weight: 600;\n}\n.error { color: #f87171; font-size: 13px; margin-top: 10px; }\n\n.cbar {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  padding: 10px 16px;\n  border-bottom: 1px solid #22262c;\n  position: sticky;\n  top: 0;\n  background: var(--bg);\n  z-index: 10;\n}\n.cbar-left h1 { font-size: 16px; margin: 0; }\n.cbar-left { display: flex; flex-direction: column; }\n.ctabs { display: flex; gap: 6px; flex: 1; }\n.ctab {\n  background: var(--surface);\n  color: var(--text-dim);\n  border: none;\n  border-radius: 8px;\n  padding: 8px 14px;\n  font-size: 13px;\n  font-weight: 600;\n}\n.ctab.active { background: var(--brand); color: #fff; }\n.panic-btn {\n  background: var(--danger);\n  color: #fff;\n  border: none;\n  border-radius: 8px;\n  padding: 10px 16px;\n  font-weight: 700;\n}\n\nmain { padding: 16px; }\n.ctab-panel { display: none; }\n.ctab-panel.active { display: block; }\n\n.grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));\n  gap: 8px;\n}\n.gtile {\n  position: relative;\n  background: var(--surface);\n  border-radius: 10px;\n  overflow: hidden;\n  cursor: pointer;\n  border: 2px solid transparent;\n}\n.gtile.focused { border-color: var(--accent); }\n.gtile img, .gtile video { width: 100%; height: 140px; object-fit: cover; display: block; background: #000; }\n.gtile .gmeta {\n  position: absolute; left: 0; right: 0; bottom: 0;\n  background: linear-gradient(to top, rgba(0,0,0,.8), transparent);\n  padding: 16px 6px 4px;\n  font-size: 11px;\n}\n.gtile .gstatus {\n  position: absolute; top: 4px; left: 4px;\n  font-size: 10px;\n  padding: 2px 6px;\n  border-radius: 6px;\n  background: rgba(0,0,0,.6);\n}\n.gstatus.pending { background: #92400e; }\n.gstatus.hidden { background: #4b5563; }\n.gtile .gfeatured { position: absolute; top: 4px; right: 4px; font-size: 14px; }\n\n.led-controls { max-width: 560px; }\n.scene-switch { display: flex; flex-direction: column; gap: 8px; margin-bottom: 20px; }\n.scene-btn {\n  background: var(--surface);\n  color: var(--text);\n  border: 1px solid #2a2f36;\n  border-radius: 10px;\n  padding: 12px;\n  text-align: left;\n  font-size: 14px;\n}\n.scene-btn.active { background: var(--brand); border-color: var(--brand); color: #fff; }\n.scene-btn:disabled { opacity: .4; cursor: default; }\n.led-row { margin-bottom: 16px; display: flex; align-items: center; gap: 10px; }\n.led-row input[type=\"number\"] {\n  width: 90px;\n  padding: 8px;\n  border-radius: 8px;\n  border: 1px solid #2a2f36;\n  background: var(--surface-2);\n  color: var(--text);\n}\n.led-row button, #saveSettings, #copyLink, #downloadQr, #exportZip {\n  background: var(--brand);\n  color: #fff;\n  border: none;\n  border-radius: 8px;\n  padding: 8px 14px;\n  font-weight: 600;\n}\n\n.setup-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 16px;\n}\n.setup-card {\n  background: var(--surface);\n  border-radius: 12px;\n  padding: 16px;\n}\n.setup-card h2 { font-size: 14px; margin: 0 0 12px; }\n.setup-card label {\n  display: block;\n  font-size: 12px;\n  color: var(--text-dim);\n  margin-bottom: 10px;\n}\n.setup-card input[type=\"text\"], .setup-card textarea {\n  width: 100%;\n  margin-top: 4px;\n  padding: 8px 10px;\n  border-radius: 8px;\n  border: 1px solid #2a2f36;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 13px;\n}\n.qr { background: #fff; padding: 10px; border-radius: 10px; display: inline-block; }\n.link-row { display: flex; gap: 8px; margin: 12px 0; }\n.link-row input {\n  flex: 1;\n  padding: 8px 10px;\n  border-radius: 8px;\n  border: 1px solid #2a2f36;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 12px;\n}\n.stats-list { list-style: none; padding: 0; margin: 0 0 14px; font-size: 13px; display: flex; flex-direction: column; gap: 6px; }\n\n.lightbox {\n  position: fixed; inset: 0; background: rgba(0,0,0,.85);\n  z-index: 50; display: flex; flex-direction: column; align-items: center; justify-content: center;\n  padding: 20px;\n}\n.lb-close { position: absolute; top: 16px; right: 16px; background: rgba(255,255,255,.1); color: #fff; border: none; width: 36px; height: 36px; border-radius: 50%; font-size: 16px; }\n.lb-media { max-width: 80vw; max-height: 60vh; display: flex; align-items: center; justify-content: center; }\n.lb-media img, .lb-media video { max-width: 100%; max-height: 60vh; border-radius: 8px; }\n.lb-info { display: flex; gap: 16px; margin-top: 12px; font-size: 13px; color: var(--text-dim); }\n.lb-actions { display: flex; gap: 10px; margin-top: 16px; }\n.lb-actions button {\n  background: var(--surface);\n  color: var(--text);\n  border: 1px solid #2a2f36;\n  border-radius: 8px;\n  padding: 10px 16px;\n  font-weight: 600;\n}\n.lb-actions button.danger { background: var(--danger); border-color: var(--danger); color: #fff; }\n\n.toast {\n  position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);\n  background: rgba(20,20,20,.95); color: #fff; padding: 10px 16px; border-radius: 999px;\n  font-size: 13px; z-index: 200;\n}\n",
  "guest/app.js": "// Guest app bootstrap: loads the event by slug, applies branding, wires tabs.\n(function () {\n  let toastTimer;\n  function toast(message) {\n    const t = document.getElementById(\"toast\");\n    t.textContent = message;\n    t.hidden = false;\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(() => (t.hidden = true), 2200);\n  }\n\n  function slugFromPath() {\n    const m = location.pathname.match(/\\/e\\/([^/]+)$/);\n    return m ? m[1] : null;\n  }\n\n  function applyBranding(event) {\n    document.documentElement.style.setProperty(\"--brand\", event.brand_color || \"#0F766E\");\n    document.documentElement.style.setProperty(\"--accent\", event.accent_color || \"#F59E0B\");\n    document.getElementById(\"eventName\").textContent = event.name;\n    document.getElementById(\"eventTagline\").textContent = event.tagline || \"\";\n    document.title = `${event.name} — InsPhoto`;\n    if (event.logo_url) {\n      const logo = document.getElementById(\"logo\");\n      logo.src = event.logo_url;\n      logo.hidden = false;\n    }\n  }\n\n  function setupTabs() {\n    const tabs = document.querySelectorAll(\".tab\");\n    tabs.forEach((btn) => {\n      btn.addEventListener(\"click\", () => switchTab(btn.dataset.tab));\n    });\n    document.getElementById(\"emptyUploadBtn\").addEventListener(\"click\", () => switchTab(\"upload\"));\n  }\n\n  function switchTab(name) {\n    document.querySelectorAll(\".tab\").forEach((b) => b.classList.toggle(\"active\", b.dataset.tab === name));\n    document.querySelectorAll(\".panel\").forEach((p) => p.classList.remove(\"active\"));\n    document.getElementById(`panel-${name}`).classList.add(\"active\");\n    if (name === \"ranking\") window.InsphotoRanking.onShow();\n    else window.InsphotoRanking.onHide();\n  }\n\n  function setupNotice(event) {\n    const key = `insphoto_notice_${event.id}`;\n    if (localStorage.getItem(key)) return;\n    const notice = document.getElementById(\"notice\");\n    const text = document.getElementById(\"noticeText\");\n    text.textContent =\n      event.welcome_message ||\n      \"Photos you upload may be shown on the event screen and this shared album.\";\n    notice.hidden = false;\n    document.getElementById(\"noticeOk\").addEventListener(\"click\", () => {\n      localStorage.setItem(key, \"1\");\n      notice.hidden = true;\n    });\n  }\n\n  async function boot() {\n    const slug = slugFromPath();\n    if (!slug) {\n      document.body.innerHTML = \"<p style='padding:40px;text-align:center'>Event not found.</p>\";\n      return;\n    }\n\n    const { data: event, error } = await window.Insphoto.supabase\n      .from(\"album_events\")\n      .select(\"*\")\n      .eq(\"slug\", slug)\n      .single();\n\n    if (error || !event) {\n      document.body.innerHTML =\n        \"<p style='padding:40px;text-align:center'>This event link isn't valid.</p>\";\n      return;\n    }\n\n    applyBranding(event);\n    setupNotice(event);\n    setupTabs();\n\n    window.InsphotoFeed.init(event);\n    window.InsphotoRanking.init(event);\n    window.InsphotoPhotoView.init(event);\n    window.InsphotoUpload.init(event);\n\n    // Keep branding/toggles live if the host changes them mid-event.\n    window.Insphoto.supabase\n      .channel(`event:${event.id}`)\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_events\", filter: `id=eq.${event.id}` },\n        (payload) => applyBranding(payload.new),\n      )\n      .subscribe();\n  }\n\n  window.InsphotoApp = { toast };\n  document.addEventListener(\"DOMContentLoaded\", boot);\n})();\n",
  "guest/feed.js": "// Explore tab: masonry grid, infinite scroll, realtime insert/delete, lazy\n// thumb loading. PRD §6.1.\n(function () {\n  const PAGE_SIZE = 60;\n\n  const state = {\n    event: null,\n    columns: [],\n    columnEls: [],\n    offset: 0,\n    done: false,\n    loading: false,\n    io: null, // sentinel observer\n    lazyIo: null,\n    seen: new Set(), // media ids already rendered, avoids dupes from realtime + pagination race\n    list: [], // ordered ids, for photo-view swipe navigation\n  };\n\n  function columnCount() {\n    return window.innerWidth >= 720 ? 4 : 2;\n  }\n\n  function buildColumns() {\n    const grid = document.getElementById(\"feedGrid\");\n    grid.innerHTML = \"\";\n    const n = columnCount();\n    state.columns = Array.from({ length: n }, () => []);\n    state.columnEls = Array.from({ length: n }, () => {\n      const col = document.createElement(\"div\");\n      col.className = \"masonry-col\";\n      grid.appendChild(col);\n      return col;\n    });\n  }\n\n  function shortestColumnIndex() {\n    let idx = 0;\n    let min = Infinity;\n    state.columnEls.forEach((el, i) => {\n      const h = el.getBoundingClientRect().height;\n      if (h < min) {\n        min = h;\n        idx = i;\n      }\n    });\n    return idx;\n  }\n\n  function tile(media) {\n    const btn = document.createElement(\"button\");\n    btn.className = \"tile\";\n    btn.dataset.id = media.id;\n\n    const img = document.createElement(\"img\");\n    img.dataset.src = window.Insphoto.mediaUrl(media.thumb_path || media.storage_path);\n    img.alt = media.caption || \"\";\n    if (media.width && media.height) {\n      img.style.aspectRatio = `${media.width} / ${media.height}`;\n    }\n    btn.appendChild(img);\n\n    if (media.uploader_name) {\n      const cap = document.createElement(\"div\");\n      cap.className = \"tile-caption\";\n      cap.textContent = media.uploader_name;\n      btn.appendChild(cap);\n    }\n    if (media.kind === \"video\") {\n      const b = document.createElement(\"div\");\n      b.className = \"badge\";\n      b.textContent = \"▶ video\";\n      btn.appendChild(b);\n    }\n\n    btn.addEventListener(\"click\", () =>\n      window.InsphotoPhotoView.open(media.id, state.list),\n    );\n\n    if (state.lazyIo) state.lazyIo.observe(img);\n    else img.src = img.dataset.src;\n\n    return btn;\n  }\n\n  function appendMedia(list, { prepend = false } = {}) {\n    for (const media of list) {\n      if (state.seen.has(media.id)) continue;\n      state.seen.add(media.id);\n      if (prepend) state.list.unshift(media.id);\n      else state.list.push(media.id);\n      const el = tile(media);\n      if (prepend) el.classList.add(\"new\");\n      const idx = prepend ? 0 : shortestColumnIndex();\n      const col = state.columnEls[idx];\n      if (prepend) col.insertBefore(el, col.firstChild);\n      else col.appendChild(el);\n    }\n    updateEmptyState();\n  }\n\n  function removeMedia(id) {\n    const el = document.querySelector(`#feedGrid .tile[data-id=\"${id}\"]`);\n    if (!el) return;\n    el.classList.add(\"removing\");\n    setTimeout(() => el.remove(), 260);\n    state.seen.delete(id);\n    const idx = state.list.indexOf(id);\n    if (idx !== -1) state.list.splice(idx, 1);\n    updateEmptyState();\n  }\n\n  function updateEmptyState() {\n    const empty = document.getElementById(\"feedEmpty\");\n    empty.hidden = state.seen.size > 0;\n  }\n\n  async function loadMore() {\n    if (state.loading || state.done || !state.event) return;\n    state.loading = true;\n    const { data, error } = await window.Insphoto.supabase\n      .from(\"album_media\")\n      .select(\"*\")\n      .eq(\"event_id\", state.event.id)\n      .order(\"created_at\", { ascending: false })\n      .range(state.offset, state.offset + PAGE_SIZE - 1);\n\n    state.loading = false;\n    if (error) {\n      console.error(error);\n      return;\n    }\n    if (!data || data.length < PAGE_SIZE) state.done = true;\n    state.offset += data.length;\n    appendMedia(data);\n  }\n\n  function setupInfiniteScroll() {\n    if (state.io) state.io.disconnect();\n    state.io = new IntersectionObserver(\n      (entries) => {\n        if (entries.some((e) => e.isIntersecting)) loadMore();\n      },\n      { rootMargin: \"600px\" },\n    );\n    state.io.observe(document.getElementById(\"feedSentinel\"));\n  }\n\n  function setupLazyLoad() {\n    state.lazyIo = new IntersectionObserver(\n      (entries) => {\n        for (const entry of entries) {\n          if (entry.isIntersecting) {\n            const img = entry.target;\n            if (img.dataset.src) img.src = img.dataset.src;\n            state.lazyIo.unobserve(img);\n          }\n        }\n      },\n      { rootMargin: \"300px\" },\n    );\n  }\n\n  function setupRealtime() {\n    window.Insphoto.supabase\n      .channel(`feed:${state.event.id}`)\n      .on(\n        \"postgres_changes\",\n        { event: \"INSERT\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => appendMedia([payload.new], { prepend: true }),\n      )\n      .on(\n        \"postgres_changes\",\n        { event: \"DELETE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => removeMedia(payload.old.id),\n      )\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => {\n          // Covers approve (pending -> approved becoming visible for the first time).\n          if (!state.seen.has(payload.new.id) && payload.new.status === \"approved\") {\n            appendMedia([payload.new], { prepend: true });\n          }\n        },\n      )\n      .on(\"broadcast\", { event: \"media_hidden\" }, (msg) => removeMedia(msg.payload.id))\n      .subscribe();\n  }\n\n  function init(event) {\n    state.event = event;\n    state.offset = 0;\n    state.done = false;\n    state.seen = new Set();\n    setupLazyLoad();\n    buildColumns();\n    setupInfiniteScroll();\n    setupRealtime();\n    loadMore();\n\n    let resizeTimer;\n    window.addEventListener(\"resize\", () => {\n      clearTimeout(resizeTimer);\n      resizeTimer = setTimeout(() => {\n        if (columnCount() !== state.columnEls.length) {\n          // Column count changed (phone <-> tablet width) — rebuild the grid\n          // from scratch rather than trying to reflow tiles across columns.\n          state.seen = new Set();\n          state.list = [];\n          state.offset = 0;\n          state.done = false;\n          buildColumns();\n          loadMore();\n        }\n      }, 200);\n    });\n  }\n\n  window.InsphotoFeed = { init, removeMedia, appendMedia };\n})();\n",
  "guest/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1\" />\n<title>InsPhoto</title>\n<link rel=\"stylesheet\" href=\"./style.css\" />\n</head>\n<body>\n  <div id=\"notice\" class=\"notice\" hidden>\n    <p id=\"noticeText\"></p>\n    <button id=\"noticeOk\">Got it</button>\n  </div>\n\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <img id=\"logo\" class=\"logo\" hidden />\n      <div>\n        <h1 id=\"eventName\">InsPhoto</h1>\n        <p id=\"eventTagline\" class=\"tagline\"></p>\n      </div>\n    </div>\n  </header>\n\n  <nav class=\"tabs\">\n    <button class=\"tab active\" data-tab=\"explore\">Explore</button>\n    <button class=\"tab\" data-tab=\"upload\">Upload</button>\n    <button class=\"tab\" data-tab=\"ranking\">Ranking</button>\n  </nav>\n\n  <main>\n    <section id=\"panel-explore\" class=\"panel active\">\n      <div id=\"feedEmpty\" class=\"empty\" hidden>\n        <p>No photos yet — be the first to add one.</p>\n        <button id=\"emptyUploadBtn\">Add a photo</button>\n      </div>\n      <div id=\"feedGrid\" class=\"masonry\"></div>\n      <div id=\"feedSentinel\" class=\"sentinel\"></div>\n    </section>\n\n    <section id=\"panel-upload\" class=\"panel\">\n      <div id=\"nameRow\" class=\"name-row\">\n        <label>Your name (optional)</label>\n        <div class=\"name-inputs\">\n          <input id=\"nameInput\" type=\"text\" placeholder=\"Stay anonymous\" maxlength=\"40\" />\n          <button id=\"nameSave\">Save</button>\n        </div>\n      </div>\n      <div class=\"upload-actions\">\n        <label class=\"upload-btn\">\n          📷 Camera\n          <input id=\"cameraInput\" type=\"file\" accept=\"image/*,video/*\" capture=\"environment\" hidden />\n        </label>\n        <label class=\"upload-btn\">\n          🖼️ Gallery\n          <input id=\"galleryInput\" type=\"file\" accept=\"image/*,video/*\" multiple hidden />\n        </label>\n      </div>\n      <ul id=\"uploadList\" class=\"upload-list\"></ul>\n    </section>\n\n    <section id=\"panel-ranking\" class=\"panel\">\n      <div id=\"rankingGrid\" class=\"masonry\"></div>\n    </section>\n  </main>\n\n  <div id=\"photoView\" class=\"photo-view\" hidden>\n    <button id=\"pvClose\" class=\"pv-close\" aria-label=\"Close\">✕</button>\n    <div class=\"pv-stage\">\n      <button id=\"pvPrev\" class=\"pv-nav pv-prev\" aria-label=\"Previous\">‹</button>\n      <div id=\"pvMediaWrap\" class=\"pv-media-wrap\"></div>\n      <button id=\"pvNext\" class=\"pv-nav pv-next\" aria-label=\"Next\">›</button>\n    </div>\n    <div class=\"pv-info\">\n      <div class=\"pv-meta\">\n        <span id=\"pvUploader\"></span>\n        <span id=\"pvCaption\"></span>\n      </div>\n      <div class=\"pv-actions\">\n        <button id=\"pvLike\" class=\"pv-like\">❤️ 0 · 0 people</button>\n        <button id=\"pvShare\">Share</button>\n        <button id=\"pvMore\">⋯</button>\n        <button id=\"pvDelete\" hidden>Delete</button>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"downloadSheet\" class=\"sheet\" hidden>\n    <div class=\"sheet-body\">\n      <button id=\"dlStandard\">Standard (1920px)</button>\n      <button id=\"dlHigh\">High quality (original)</button>\n      <button id=\"dlCancel\">Cancel</button>\n    </div>\n  </div>\n\n  <div id=\"toast\" class=\"toast\" hidden></div>\n\n  <script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js\"></script>\n  <script src=\"../shared/format.js\"></script>\n  <script src=\"../shared/device.js\"></script>\n  <script src=\"../shared/supabase-init.js\"></script>\n  <script src=\"./feed.js\"></script>\n  <script src=\"./photoview.js\"></script>\n  <script src=\"./ranking.js\"></script>\n  <script src=\"./upload.js\"></script>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n",
  "guest/photoview.js": "// Fullscreen photo view: like batching, share, download, swipe, self-delete.\n// PRD §6.2.\n(function () {\n  const LIKE_FLUSH_IDLE_MS = 800;\n  const LIKE_CHUNK = 100;\n\n  const state = {\n    event: null,\n    contextList: [],\n    index: -1,\n    media: null, // currently displayed row\n    pendingLikes: 0,\n    flushTimer: null,\n    flushing: false,\n    swipeStartX: null,\n    swipeStartY: null,\n    longPressTimer: null,\n  };\n\n  const el = {};\n  function cacheEls() {\n    el.root = document.getElementById(\"photoView\");\n    el.close = document.getElementById(\"pvClose\");\n    el.wrap = document.getElementById(\"pvMediaWrap\");\n    el.prev = document.getElementById(\"pvPrev\");\n    el.next = document.getElementById(\"pvNext\");\n    el.uploader = document.getElementById(\"pvUploader\");\n    el.caption = document.getElementById(\"pvCaption\");\n    el.like = document.getElementById(\"pvLike\");\n    el.share = document.getElementById(\"pvShare\");\n    el.more = document.getElementById(\"pvMore\");\n    el.del = document.getElementById(\"pvDelete\");\n    el.sheet = document.getElementById(\"downloadSheet\");\n    el.dlStandard = document.getElementById(\"dlStandard\");\n    el.dlHigh = document.getElementById(\"dlHigh\");\n    el.dlCancel = document.getElementById(\"dlCancel\");\n  }\n\n  function flushPendingLikes(immediate) {\n    if (state.pendingLikes <= 0 || !state.media) return;\n    clearTimeout(state.flushTimer);\n    const run = async () => {\n      if (state.flushing) return;\n      state.flushing = true;\n      let toSend = state.pendingLikes;\n      state.pendingLikes = 0;\n      const mediaId = state.media.id;\n      const deviceId = window.InsphotoDevice.deviceId();\n      while (toSend > 0) {\n        const chunk = Math.min(toSend, LIKE_CHUNK);\n        toSend -= chunk;\n        try {\n          const { data, error } = await window.Insphoto.supabase.rpc(\"album_like\", {\n            p_media: mediaId,\n            p_device: deviceId,\n            p_n: chunk,\n          });\n          if (error) throw error;\n          if (data && data[0] && state.media && state.media.id === mediaId) {\n            state.media.like_count = data[0].like_count;\n            state.media.liker_count = data[0].liker_count;\n            renderLike();\n          }\n        } catch (e) {\n          // Keep the local optimistic count, retry once by re-queueing.\n          state.pendingLikes += chunk;\n          console.error(\"like flush failed\", e);\n          break;\n        }\n      }\n      state.flushing = false;\n    };\n    if (immediate) run();\n    else state.flushTimer = setTimeout(run, LIKE_FLUSH_IDLE_MS);\n  }\n\n  function renderLike() {\n    if (!state.media) return;\n    el.like.textContent = window.InsphotoFormat.likeLabel(\n      state.media.like_count || 0,\n      state.media.liker_count || 0,\n    );\n  }\n\n  function tapLike() {\n    if (!state.media) return;\n    state.media.like_count = (state.media.like_count || 0) + 1;\n    // liker_count only increases server-side on a device's first ever like —\n    // we don't know that client-side, so we leave it alone optimistically.\n    renderLike();\n    el.like.classList.remove(\"tapped\");\n    void el.like.offsetWidth;\n    el.like.classList.add(\"tapped\");\n    state.pendingLikes += 1;\n    clearTimeout(state.flushTimer);\n    state.flushTimer = setTimeout(() => flushPendingLikes(false), LIKE_FLUSH_IDLE_MS);\n  }\n\n  function renderMedia() {\n    const m = state.media;\n    el.wrap.innerHTML = \"\";\n    if (m.kind === \"video\") {\n      const video = document.createElement(\"video\");\n      video.src = window.Insphoto.mediaUrl(m.storage_path);\n      video.controls = true;\n      video.autoplay = true;\n      video.playsInline = true;\n      video.style.webkitTouchCallout = \"none\";\n      el.wrap.appendChild(video);\n    } else {\n      const img = document.createElement(\"img\");\n      img.src = window.Insphoto.mediaUrl(m.storage_path);\n      img.alt = m.caption || \"\";\n      img.style.webkitTouchCallout = \"none\";\n      el.wrap.appendChild(img);\n    }\n    el.uploader.textContent = m.uploader_name || \"Anonymous\";\n    el.caption.textContent = m.caption || \"\";\n    renderLike();\n\n    const isMine = m.device_id && m.device_id === window.InsphotoDevice.deviceId();\n    el.del.hidden = !(isMine && state.event && state.event.allow_guest_delete);\n\n    el.prev.style.visibility = state.index > 0 ? \"visible\" : \"hidden\";\n    el.next.style.visibility = state.index < state.contextList.length - 1 ? \"visible\" : \"hidden\";\n  }\n\n  async function loadIndex(i) {\n    const id = state.contextList[i];\n    if (!id) return;\n    const { data, error } = await window.Insphoto.supabase\n      .from(\"album_media\")\n      .select(\"*\")\n      .eq(\"id\", id)\n      .single();\n    if (error || !data) return;\n    state.index = i;\n    state.media = data;\n    state.pendingLikes = 0;\n    renderMedia();\n  }\n\n  async function open(id, contextList) {\n    cacheEls();\n    state.contextList = contextList && contextList.length ? contextList.slice() : [id];\n    const idx = state.contextList.indexOf(id);\n    el.root.hidden = false;\n    document.body.style.overflow = \"hidden\";\n    await loadIndex(idx === -1 ? 0 : idx);\n  }\n\n  function close() {\n    flushPendingLikes(true);\n    el.root.hidden = true;\n    document.body.style.overflow = \"\";\n    el.wrap.innerHTML = \"\";\n    state.media = null;\n  }\n\n  function goPrev() {\n    if (state.index > 0) {\n      flushPendingLikes(true);\n      loadIndex(state.index - 1);\n    }\n  }\n  function goNext() {\n    if (state.index < state.contextList.length - 1) {\n      flushPendingLikes(true);\n      loadIndex(state.index + 1);\n    }\n  }\n\n  async function fetchBlob(url) {\n    const res = await fetch(url);\n    if (!res.ok) throw new Error(\"download failed\");\n    return res.blob();\n  }\n\n  async function shareCurrent() {\n    if (!state.media) return;\n    const url = window.Insphoto.mediaUrl(state.media.storage_path);\n    try {\n      if (navigator.canShare) {\n        const blob = await fetchBlob(url);\n        const file = new File([blob], \"photo.jpg\", { type: blob.type || \"image/jpeg\" });\n        if (navigator.canShare({ files: [file] })) {\n          await navigator.share({ files: [file], text: state.media.caption || \"\" });\n          return;\n        }\n      }\n      if (navigator.share) {\n        await navigator.share({ url, text: state.media.caption || \"\" });\n        return;\n      }\n      await navigator.clipboard.writeText(url);\n      window.InsphotoApp.toast(\"Link copied\");\n    } catch (e) {\n      if (e && e.name === \"AbortError\") return;\n      console.error(e);\n    }\n  }\n\n  function triggerDownload(url, filename) {\n    fetchBlob(url).then((blob) => {\n      const a = document.createElement(\"a\");\n      a.href = URL.createObjectURL(blob);\n      a.download = filename;\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n      setTimeout(() => URL.revokeObjectURL(a.href), 4000);\n    });\n  }\n\n  function openDownloadSheet() {\n    el.sheet.hidden = false;\n  }\n  function closeDownloadSheet() {\n    el.sheet.hidden = true;\n  }\n\n  async function deleteCurrent() {\n    if (!state.media) return;\n    if (!confirm(\"Delete this photo? This can't be undone.\")) return;\n    const id = state.media.id;\n    try {\n      const res = await fetch(window.Insphoto.apiPath(`/api/media/${id}/delete`), {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({ device_id: window.InsphotoDevice.deviceId() }),\n      });\n      if (!res.ok) throw new Error(await res.text());\n      window.InsphotoFeed.removeMedia(id);\n      goNextOrClose();\n    } catch (e) {\n      console.error(e);\n      window.InsphotoApp.toast(\"Could not delete photo\");\n    }\n  }\n\n  function goNextOrClose() {\n    if (state.index < state.contextList.length - 1) {\n      state.contextList.splice(state.index, 1);\n      loadIndex(state.index);\n    } else if (state.index > 0) {\n      state.contextList.splice(state.index, 1);\n      loadIndex(state.index - 1);\n    } else {\n      close();\n    }\n  }\n\n  function bindEvents() {\n    el.close.addEventListener(\"click\", close);\n    el.prev.addEventListener(\"click\", goPrev);\n    el.next.addEventListener(\"click\", goNext);\n    el.like.addEventListener(\"click\", tapLike);\n    el.share.addEventListener(\"click\", shareCurrent);\n    el.more.addEventListener(\"click\", openDownloadSheet);\n    el.del.addEventListener(\"click\", deleteCurrent);\n    el.dlCancel.addEventListener(\"click\", closeDownloadSheet);\n    el.dlStandard.addEventListener(\"click\", () => {\n      closeDownloadSheet();\n      if (state.media) {\n        triggerDownload(window.Insphoto.mediaUrl(state.media.storage_path), \"photo-standard.jpg\");\n      }\n    });\n    el.dlHigh.addEventListener(\"click\", () => {\n      closeDownloadSheet();\n      if (state.media) {\n        triggerDownload(window.Insphoto.mediaUrl(state.media.storage_path), \"photo-highres.jpg\");\n      }\n    });\n\n    document.addEventListener(\"visibilitychange\", () => {\n      if (document.hidden) flushPendingLikes(true);\n    });\n    window.addEventListener(\"pagehide\", () => flushPendingLikes(true));\n\n    document.addEventListener(\"keydown\", (e) => {\n      if (el.root.hidden) return;\n      if (e.key === \"Escape\") close();\n      if (e.key === \"ArrowLeft\") goPrev();\n      if (e.key === \"ArrowRight\") goNext();\n    });\n\n    // Long-press for download (image is claimed by iOS \"Save Image\" on plain\n    // long-press, so the visible ⋯ button is the primary path — this is a\n    // secondary affordance for browsers that don't intercept it).\n    el.wrap.addEventListener(\"touchstart\", (e) => {\n      state.swipeStartX = e.touches[0].clientX;\n      state.swipeStartY = e.touches[0].clientY;\n      state.longPressTimer = setTimeout(() => openDownloadSheet(), 500);\n    });\n    el.wrap.addEventListener(\"touchmove\", (e) => {\n      if (state.swipeStartX == null) return;\n      const dx = Math.abs(e.touches[0].clientX - state.swipeStartX);\n      const dy = Math.abs(e.touches[0].clientY - state.swipeStartY);\n      if (dx > 10 || dy > 10) clearTimeout(state.longPressTimer);\n    });\n    el.wrap.addEventListener(\"touchend\", (e) => {\n      clearTimeout(state.longPressTimer);\n      if (state.swipeStartX == null) return;\n      const dx = e.changedTouches[0].clientX - state.swipeStartX;\n      const dy = e.changedTouches[0].clientY - state.swipeStartY;\n      state.swipeStartX = null;\n      if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) {\n        if (dx > 0) goPrev();\n        else goNext();\n      }\n    });\n  }\n\n  function init(event) {\n    state.event = event;\n    cacheEls();\n    bindEvents();\n  }\n\n  window.InsphotoPhotoView = { init, open, close };\n})();\n",
  "guest/ranking.js": "// Ranking tab: same grid, sorted by unique voters. PRD §6.3.\n(function () {\n  const REFRESH_MS = 20000;\n\n  const state = {\n    event: null,\n    list: [], // ordered media rows\n    columnEls: [],\n    active: false,\n    timer: null,\n  };\n\n  function columnCount() {\n    return window.innerWidth >= 720 ? 4 : 2;\n  }\n\n  function buildColumns() {\n    const grid = document.getElementById(\"rankingGrid\");\n    grid.innerHTML = \"\";\n    const n = columnCount();\n    state.columnEls = Array.from({ length: n }, () => {\n      const col = document.createElement(\"div\");\n      col.className = \"masonry-col\";\n      grid.appendChild(col);\n      return col;\n    });\n  }\n\n  function tile(media, rank) {\n    const btn = document.createElement(\"button\");\n    btn.className = \"tile\";\n    btn.dataset.id = media.id;\n\n    const img = document.createElement(\"img\");\n    img.src = window.Insphoto.mediaUrl(media.thumb_path || media.storage_path);\n    img.alt = media.caption || \"\";\n    if (media.width && media.height) img.style.aspectRatio = `${media.width} / ${media.height}`;\n    btn.appendChild(img);\n\n    if (rank <= 3) {\n      const badge = document.createElement(\"div\");\n      badge.className = \"rank-badge\";\n      badge.textContent = String(rank);\n      btn.appendChild(badge);\n    }\n\n    const cap = document.createElement(\"div\");\n    cap.className = \"tile-caption\";\n    cap.textContent = window.InsphotoFormat.likeLabel(media.like_count, media.liker_count);\n    btn.appendChild(cap);\n\n    btn.addEventListener(\"click\", () =>\n      window.InsphotoPhotoView.open(\n        media.id,\n        state.list.map((m) => m.id),\n      ),\n    );\n    return btn;\n  }\n\n  function render() {\n    buildColumns();\n    state.list.forEach((media, i) => {\n      const el = tile(media, i + 1);\n      // Round-robin placement keeps rank order readable left-to-right.\n      const col = state.columnEls[i % state.columnEls.length];\n      col.appendChild(el);\n    });\n  }\n\n  async function refresh() {\n    if (!state.event) return;\n    const { data, error } = await window.Insphoto.supabase\n      .from(\"album_media\")\n      .select(\"*\")\n      .eq(\"event_id\", state.event.id)\n      .order(\"liker_count\", { ascending: false })\n      .order(\"like_count\", { ascending: false })\n      .limit(120);\n    if (error) {\n      console.error(error);\n      return;\n    }\n    state.list = data || [];\n    if (state.active) render();\n  }\n\n  function startTimer() {\n    clearInterval(state.timer);\n    state.timer = setInterval(refresh, REFRESH_MS);\n  }\n\n  function setupRealtime() {\n    window.Insphoto.supabase\n      .channel(`ranking:${state.event.id}`)\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        () => refresh(),\n      )\n      .on(\n        \"postgres_changes\",\n        { event: \"DELETE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        () => refresh(),\n      )\n      .subscribe();\n  }\n\n  function onShow() {\n    state.active = true;\n    render();\n  }\n  function onHide() {\n    state.active = false;\n  }\n\n  function init(event) {\n    state.event = event;\n    refresh();\n    startTimer();\n    setupRealtime();\n\n    let resizeTimer;\n    window.addEventListener(\"resize\", () => {\n      clearTimeout(resizeTimer);\n      resizeTimer = setTimeout(() => {\n        if (state.active) render();\n      }, 200);\n    });\n  }\n\n  window.InsphotoRanking = { init, onShow, onHide };\n})();\n",
  "guest/style.css": ":root {\n  --brand: #0F766E;\n  --accent: #F59E0B;\n  --bg: #0b0d10;\n  --surface: #15181c;\n  --surface-2: #1e2227;\n  --text: #f4f5f6;\n  --text-dim: #9aa1a9;\n  --radius: 14px;\n}\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  -webkit-tap-highlight-color: transparent;\n}\n\nbutton {\n  font-family: inherit;\n  cursor: pointer;\n}\n\n.notice {\n  position: fixed;\n  inset: auto 0 0 0;\n  background: var(--surface-2);\n  padding: 14px 16px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  z-index: 60;\n  border-top: 1px solid #2a2f36;\n}\n.notice p { margin: 0; font-size: 13px; color: var(--text-dim); }\n.notice button {\n  background: var(--accent);\n  color: #1a1200;\n  border: none;\n  border-radius: 8px;\n  padding: 8px 14px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.topbar {\n  padding: 16px 16px 8px;\n  display: flex;\n  align-items: center;\n}\n.brand { display: flex; align-items: center; gap: 10px; }\n.logo { width: 36px; height: 36px; border-radius: 8px; object-fit: cover; }\n.topbar h1 { font-size: 18px; margin: 0; }\n.tagline { margin: 2px 0 0; font-size: 12px; color: var(--text-dim); }\n\n.tabs {\n  display: flex;\n  gap: 4px;\n  padding: 0 16px 12px;\n  position: sticky;\n  top: 0;\n  background: var(--bg);\n  z-index: 20;\n}\n.tab {\n  flex: 1;\n  background: var(--surface);\n  color: var(--text-dim);\n  border: none;\n  border-radius: 999px;\n  padding: 10px 0;\n  font-size: 13px;\n  font-weight: 600;\n}\n.tab.active { background: var(--brand); color: #fff; }\n\nmain { padding: 0 8px 90px; }\n.panel { display: none; }\n.panel.active { display: block; }\n\n.empty {\n  text-align: center;\n  padding: 60px 20px;\n  color: var(--text-dim);\n}\n.empty button {\n  margin-top: 12px;\n  background: var(--brand);\n  color: #fff;\n  border: none;\n  border-radius: 10px;\n  padding: 10px 18px;\n  font-weight: 600;\n}\n\n.masonry {\n  display: flex;\n  gap: 8px;\n  align-items: flex-start;\n}\n.masonry-col {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  flex: 1;\n  min-width: 0;\n}\n.tile {\n  position: relative;\n  border-radius: var(--radius);\n  overflow: hidden;\n  background: var(--surface);\n  border: none;\n  padding: 0;\n  display: block;\n  width: 100%;\n}\n.tile img {\n  width: 100%;\n  display: block;\n  background: var(--surface-2);\n}\n.tile.new { animation: pop-in 0.35s ease; }\n@keyframes pop-in {\n  from { transform: scale(0.92); opacity: 0; }\n  to { transform: scale(1); opacity: 1; }\n}\n.tile.removing { animation: fade-out 0.25s ease forwards; }\n@keyframes fade-out { to { opacity: 0; transform: scale(0.95); } }\n\n.tile .tile-caption {\n  position: absolute;\n  left: 0; right: 0; bottom: 0;\n  padding: 18px 8px 6px;\n  font-size: 11px;\n  color: #fff;\n  background: linear-gradient(to top, rgba(0,0,0,.65), transparent);\n  text-align: left;\n}\n.tile .badge {\n  position: absolute;\n  top: 6px; left: 6px;\n  background: rgba(0,0,0,.55);\n  color: #fff;\n  font-size: 10px;\n  padding: 2px 6px;\n  border-radius: 6px;\n}\n.tile .rank-badge {\n  position: absolute;\n  top: 6px; left: 6px;\n  background: var(--accent);\n  color: #1a1200;\n  font-weight: 800;\n  font-size: 12px;\n  width: 22px; height: 22px;\n  border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n}\n\n.sentinel { height: 1px; }\n\n.name-row { padding: 12px 8px; }\n.name-row label { font-size: 12px; color: var(--text-dim); }\n.name-inputs { display: flex; gap: 8px; margin-top: 6px; }\n.name-inputs input {\n  flex: 1;\n  background: var(--surface);\n  border: 1px solid #2a2f36;\n  color: var(--text);\n  border-radius: 10px;\n  padding: 10px 12px;\n  font-size: 14px;\n}\n.name-inputs button {\n  background: var(--brand);\n  color: #fff;\n  border: none;\n  border-radius: 10px;\n  padding: 0 16px;\n  font-weight: 600;\n}\n\n.upload-actions {\n  display: flex;\n  gap: 10px;\n  padding: 4px 8px 14px;\n}\n.upload-btn {\n  flex: 1;\n  text-align: center;\n  background: var(--surface);\n  border: 1px dashed #3a4048;\n  border-radius: var(--radius);\n  padding: 22px 10px;\n  font-size: 14px;\n  font-weight: 600;\n}\n\n.upload-list { list-style: none; margin: 0; padding: 0 8px; display: flex; flex-direction: column; gap: 8px; }\n.upload-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  background: var(--surface);\n  border-radius: 10px;\n  padding: 8px;\n}\n.upload-item img { width: 44px; height: 44px; object-fit: cover; border-radius: 8px; }\n.upload-item .u-info { flex: 1; min-width: 0; }\n.upload-item .u-name { font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.upload-item .u-bar { height: 4px; background: #2a2f36; border-radius: 4px; margin-top: 6px; overflow: hidden; }\n.upload-item .u-bar-fill { height: 100%; background: var(--brand); width: 0%; transition: width .2s; }\n.upload-item .u-status { font-size: 11px; color: var(--text-dim); }\n.upload-item .u-status.error { color: #f87171; }\n.upload-item .u-status.done { color: #4ade80; }\n\n/* Photo view */\n.photo-view {\n  position: fixed;\n  inset: 0;\n  background: #000;\n  z-index: 100;\n  display: flex;\n  flex-direction: column;\n}\n.pv-close {\n  position: absolute;\n  top: max(10px, env(safe-area-inset-top));\n  right: 10px;\n  z-index: 5;\n  background: rgba(0,0,0,.5);\n  color: #fff;\n  border: none;\n  width: 36px; height: 36px;\n  border-radius: 50%;\n  font-size: 16px;\n}\n.pv-stage { position: relative; flex: 1; display: flex; align-items: center; justify-content: center; overflow: hidden; }\n.pv-media-wrap { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; touch-action: pan-y; }\n.pv-media-wrap img, .pv-media-wrap video { max-width: 100%; max-height: 100%; -webkit-touch-callout: none; }\n.pv-nav {\n  position: absolute;\n  top: 50%; transform: translateY(-50%);\n  background: rgba(0,0,0,.4);\n  color: #fff;\n  border: none;\n  width: 40px; height: 40px;\n  border-radius: 50%;\n  font-size: 22px;\n  z-index: 4;\n}\n.pv-prev { left: 8px; }\n.pv-next { right: 8px; }\n.pv-info { padding: 10px 14px max(14px, env(safe-area-inset-bottom)); background: #0a0a0a; }\n.pv-meta { display: flex; flex-direction: column; gap: 2px; margin-bottom: 10px; }\n.pv-meta span { font-size: 13px; color: var(--text-dim); }\n#pvUploader { color: #fff; font-weight: 600; }\n.pv-actions { display: flex; gap: 8px; }\n.pv-actions button {\n  flex: 1;\n  background: var(--surface);\n  color: #fff;\n  border: none;\n  border-radius: 10px;\n  padding: 12px 0;\n  font-size: 13px;\n  font-weight: 600;\n  min-height: 44px;\n}\n.pv-like { background: #7f1d1d !important; }\n.pv-like.tapped { animation: heart-pop .25s ease; }\n@keyframes heart-pop { 0% { transform: scale(1); } 50% { transform: scale(1.12); } 100% { transform: scale(1); } }\n#pvDelete { background: #7f1d1d !important; flex: 0 0 auto; padding: 12px 16px; }\n\n.sheet {\n  position: fixed;\n  inset: 0;\n  background: rgba(0,0,0,.5);\n  z-index: 110;\n  display: flex;\n  align-items: flex-end;\n}\n.sheet-body {\n  background: var(--surface);\n  width: 100%;\n  border-radius: 16px 16px 0 0;\n  padding: 10px 14px max(14px, env(safe-area-inset-bottom));\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.sheet-body button {\n  background: var(--surface-2);\n  color: #fff;\n  border: none;\n  border-radius: 10px;\n  padding: 14px;\n  font-size: 14px;\n  min-height: 44px;\n}\n\n.toast {\n  position: fixed;\n  left: 50%;\n  bottom: max(20px, env(safe-area-inset-bottom));\n  transform: translateX(-50%);\n  background: rgba(20,20,20,.95);\n  color: #fff;\n  padding: 10px 16px;\n  border-radius: 999px;\n  font-size: 13px;\n  z-index: 200;\n}\n\n@media (min-width: 720px) {\n  main { max-width: 960px; margin: 0 auto; }\n  .topbar, .tabs { max-width: 960px; margin: 0 auto; width: 100%; }\n}\n",
  "guest/upload.js": "// Upload flow: client-side resize, presign, direct-to-R2 PUT, then a normal\n// insert of the album_media row. PRD §6.4.\n(function () {\n  const MAX_RETRIES = 3;\n  const PRESIGN_SAFETY_MS = 4.5 * 60 * 1000; // re-presign once we're this close to the 5 min expiry\n\n  const state = {\n    event: null,\n  };\n\n  function el(id) {\n    return document.getElementById(id);\n  }\n\n  function extFromType(type, fallback) {\n    if (!type) return fallback;\n    const m = type.match(/\\/([a-z0-9]+)$/i);\n    return m ? m[1].toLowerCase() : fallback;\n  }\n\n  function loadImage(file) {\n    return new Promise((resolve, reject) => {\n      if (\"createImageBitmap\" in window) {\n        createImageBitmap(file).then(resolve).catch(reject);\n      } else {\n        reject(new Error(\"createImageBitmap unsupported\"));\n      }\n    });\n  }\n\n  async function resizeToBlob(bitmap, maxEdge, quality) {\n    const scale = Math.min(1, maxEdge / Math.max(bitmap.width, bitmap.height));\n    const w = Math.max(1, Math.round(bitmap.width * scale));\n    const h = Math.max(1, Math.round(bitmap.height * scale));\n    const canvas = document.createElement(\"canvas\");\n    canvas.width = w;\n    canvas.height = h;\n    const ctx = canvas.getContext(\"2d\");\n    ctx.drawImage(bitmap, 0, 0, w, h);\n    const blob = await new Promise((resolve) =>\n      canvas.toBlob(resolve, \"image/jpeg\", quality),\n    );\n    return { blob, width: w, height: h };\n  }\n\n  function xhrPut(url, blob, contentType, onProgress) {\n    return new Promise((resolve, reject) => {\n      const xhr = new XMLHttpRequest();\n      xhr.open(\"PUT\", url);\n      xhr.setRequestHeader(\"content-type\", contentType);\n      xhr.upload.onprogress = (e) => {\n        if (e.lengthComputable) onProgress(e.loaded / e.total);\n      };\n      xhr.onload = () => {\n        if (xhr.status >= 200 && xhr.status < 300) resolve();\n        else reject(new Error(`upload failed: ${xhr.status}`));\n      };\n      xhr.onerror = () => reject(new Error(\"network error during upload\"));\n      xhr.send(blob);\n    });\n  }\n\n  async function presign(files) {\n    const res = await fetch(window.Insphoto.apiPath(\"/api/presign\"), {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ event_id: state.event.id, files }),\n    });\n    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || \"presign failed\");\n    return (await res.json()).files; // [{part,key,url,expiresAt}]\n  }\n\n  function sleep(ms) {\n    return new Promise((r) => setTimeout(r, ms));\n  }\n\n  function makeItemUI(file) {\n    const li = document.createElement(\"li\");\n    li.className = \"upload-item\";\n    const thumb = document.createElement(\"img\");\n    if (file.type.startsWith(\"image/\")) {\n      thumb.src = URL.createObjectURL(file);\n    } else {\n      thumb.style.background = \"#2a2f36\";\n    }\n    const info = document.createElement(\"div\");\n    info.className = \"u-info\";\n    const name = document.createElement(\"div\");\n    name.className = \"u-name\";\n    name.textContent = file.name;\n    const bar = document.createElement(\"div\");\n    bar.className = \"u-bar\";\n    const fill = document.createElement(\"div\");\n    fill.className = \"u-bar-fill\";\n    bar.appendChild(fill);\n    const status = document.createElement(\"div\");\n    status.className = \"u-status\";\n    status.textContent = \"Preparing…\";\n    info.append(name, bar, status);\n    li.append(thumb, info);\n    el(\"uploadList\").prepend(li);\n    return { fill, status };\n  }\n\n  async function putWithRetry(part, blob, contentType, ext, ui, weight, baseProgress) {\n    let attempt = 0;\n    let presigned = null;\n    let presignedAt = 0;\n    while (attempt < MAX_RETRIES) {\n      attempt++;\n      try {\n        if (!presigned || Date.now() - presignedAt > PRESIGN_SAFETY_MS) {\n          const files = await presign([{ part, content_type: contentType, ext }]);\n          presigned = files[0];\n          presignedAt = Date.now();\n        }\n        await xhrPut(presigned.url, blob, contentType, (p) => {\n          ui.fill.style.width = `${Math.round((baseProgress + p * weight) * 100)}%`;\n        });\n        return presigned.key;\n      } catch (e) {\n        if (attempt >= MAX_RETRIES) throw e;\n        await sleep(2 ** (attempt - 1) * 1000);\n        presigned = null; // force a fresh presign on retry\n      }\n    }\n    throw new Error(\"upload failed\");\n  }\n\n  async function processImage(file, ui) {\n    let bitmap;\n    try {\n      bitmap = await loadImage(file);\n    } catch {\n      // HEIC or otherwise undecodable — fall back to uploading the original.\n      const key = await putWithRetry(\n        \"display\",\n        file,\n        file.type || \"application/octet-stream\",\n        extFromType(file.type, \"jpg\"),\n        ui,\n        1,\n        0,\n      );\n      return { storage_path: key, thumb_path: null, width: null, height: null, bytes: file.size };\n    }\n\n    const maxPx = state.event.max_photo_px || 1920;\n    const quality = state.event.jpeg_quality || 0.8;\n    const display = await resizeToBlob(bitmap, maxPx, quality);\n    const thumb = await resizeToBlob(bitmap, 480, 0.72);\n\n    const displayKey = await putWithRetry(\"display\", display.blob, \"image/jpeg\", \"jpg\", ui, 0.75, 0);\n    const thumbKey = await putWithRetry(\"thumb\", thumb.blob, \"image/jpeg\", \"jpg\", ui, 0.25, 0.75);\n\n    return {\n      storage_path: displayKey,\n      thumb_path: thumbKey,\n      width: display.width,\n      height: display.height,\n      bytes: display.blob.size,\n    };\n  }\n\n  async function processVideo(file, ui) {\n    const key = await putWithRetry(\n      \"video\",\n      file,\n      file.type || \"video/mp4\",\n      extFromType(file.type, \"mp4\"),\n      ui,\n      1,\n      0,\n    );\n    return { storage_path: key, thumb_path: null, width: null, height: null, bytes: file.size };\n  }\n\n  async function handleFile(file) {\n    const ui = makeItemUI(file);\n    const isVideo = file.type.startsWith(\"video/\");\n\n    if (isVideo && !state.event.allow_video) {\n      ui.status.textContent = \"Videos aren't enabled for this event\";\n      ui.status.classList.add(\"error\");\n      return;\n    }\n    const maxBytes = (state.event.max_file_mb || 25) * 1024 * 1024;\n    if (file.size > maxBytes) {\n      ui.status.textContent = `Too large — max ${state.event.max_file_mb}MB`;\n      ui.status.classList.add(\"error\");\n      return;\n    }\n\n    ui.status.textContent = \"Uploading…\";\n    try {\n      const result = isVideo ? await processVideo(file, ui) : await processImage(file, ui);\n      const { error } = await window.Insphoto.supabase.from(\"album_media\").insert({\n        event_id: state.event.id,\n        storage_path: result.storage_path,\n        thumb_path: result.thumb_path,\n        kind: isVideo ? \"video\" : \"photo\",\n        width: result.width,\n        height: result.height,\n        bytes: result.bytes,\n        uploader_name: window.InsphotoDevice.guestName(),\n        device_id: window.InsphotoDevice.deviceId(),\n      });\n      if (error) throw error;\n      ui.fill.style.width = \"100%\";\n      ui.status.textContent = \"Done\";\n      ui.status.classList.add(\"done\");\n    } catch (e) {\n      console.error(e);\n      ui.status.textContent = \"Failed — tap Gallery/Camera to retry\";\n      ui.status.classList.add(\"error\");\n    }\n  }\n\n  function handleFiles(fileList) {\n    Array.from(fileList).forEach(handleFile);\n  }\n\n  function initNameField() {\n    const input = el(\"nameInput\");\n    input.value = window.InsphotoDevice.guestName();\n    el(\"nameSave\").addEventListener(\"click\", () => {\n      window.InsphotoDevice.guestName(input.value.trim());\n      window.InsphotoApp.toast(\"Name saved\");\n    });\n  }\n\n  function init(event) {\n    state.event = event;\n    initNameField();\n    el(\"cameraInput\").addEventListener(\"change\", (e) => {\n      handleFiles(e.target.files);\n      e.target.value = \"\";\n    });\n    el(\"galleryInput\").addEventListener(\"change\", (e) => {\n      handleFiles(e.target.files);\n      e.target.value = \"\";\n    });\n    if (!event.upload_open) {\n      document.querySelector(\".upload-actions\").hidden = true;\n      const p = document.createElement(\"p\");\n      p.textContent = \"Uploads are closed for this event right now.\";\n      p.style.padding = \"0 8px\";\n      p.style.color = \"var(--text-dim)\";\n      el(\"panel-upload\").prepend(p);\n    }\n  }\n\n  window.InsphotoUpload = { init };\n})();\n",
  "led/app.js": "// LED display: read-only, fullscreen, driven entirely by the console via\n// Realtime. PRD §8. No alert/confirm/dialog anywhere in this file — a\n// blocking dialog on the LED is an incident (§8.4).\n(function () {\n  const ELIGIBILITY_CHECK_MS = 5000;\n  const PHOTO_MS = 7000;\n  const VIDEO_MAX_MS = 20000;\n  const RANKING_REFRESH_MS = 15000;\n  const CACHE_LIMIT = 100;\n  const RECONNECT_BASE_MS = 1000;\n  const FORCE_RELOAD_AFTER_DISCONNECT_MS = 60000;\n\n  const state = {\n    slug: null,\n    event: null,\n    allMedia: new Map(), // id -> row\n    cachedPool: [], // ids, capped at CACHE_LIMIT, most-recent-eligible first\n    priorityQueue: [], // ids that just became eligible, shown next with a badge\n    badgeShown: new Set(),\n    rotationIndex: 0,\n    rotationTimer: null,\n    eligibilityTimer: null,\n    rankingTimer: null,\n    disconnectTimer: null,\n    reconnectAttempt: 0,\n    channel: null,\n  };\n\n  function slugFromPath() {\n    const m = location.pathname.match(/\\/s\\/([^/]+)$/);\n    return m ? m[1] : null;\n  }\n\n  function isEligible(row) {\n    if (!row || row.status !== \"approved\") return false;\n    const ageMs = Date.now() - new Date(row.created_at).getTime();\n    return ageMs > (state.event.led_delay_seconds || 0) * 1000;\n  }\n\n  function guestUrl() {\n    return `${location.origin}${window.Insphoto.apiPath(`/e/${state.slug}`)}`;\n  }\n\n  function renderJoinCard() {\n    const el = document.getElementById(\"joinQr\");\n    el.innerHTML = \"\";\n    const canvas = document.createElement(\"canvas\");\n    el.appendChild(canvas);\n    window.QRCode.toCanvas(canvas, guestUrl(), { width: 120, margin: 1 });\n  }\n\n  // ---------- scene switching ----------\n\n  function showScene(name) {\n    document.querySelectorAll(\".scene\").forEach((s) => s.classList.remove(\"active\"));\n    if (name === \"wall\") document.getElementById(\"scene-wall\").classList.add(\"active\");\n    else if (name === \"ranking\") document.getElementById(\"scene-ranking\").classList.add(\"active\");\n    else if (name === \"blank\") document.getElementById(\"scene-blank\").classList.add(\"active\");\n    else {\n      document.getElementById(\"placeholderText\").textContent =\n        name === \"winner\"\n          ? \"Winner reveal — coming in Sprint 2\"\n          : name === \"sponsor\"\n            ? \"Sponsor slate — coming in Sprint 3\"\n            : name === \"countdown\"\n              ? \"Countdown — coming in Sprint 2\"\n              : \"\";\n      document.getElementById(\"scene-placeholder\").classList.add(\"active\");\n    }\n  }\n\n  function applyScene() {\n    clearInterval(state.rankingTimer);\n    const scene = state.event.led_scene || \"wall\";\n    showScene(scene);\n    if (scene === \"wall\") {\n      startRotation();\n    } else {\n      clearTimeout(state.rotationTimer);\n      if (scene === \"ranking\") {\n        renderRanking();\n        state.rankingTimer = setInterval(renderRanking, RANKING_REFRESH_MS);\n      }\n    }\n  }\n\n  // ---------- wall scene rotation ----------\n\n  function pushToCache(id) {\n    const existing = state.cachedPool.indexOf(id);\n    if (existing !== -1) state.cachedPool.splice(existing, 1);\n    state.cachedPool.unshift(id);\n    if (state.cachedPool.length > CACHE_LIMIT) state.cachedPool.pop();\n  }\n\n  function recomputeEligibility() {\n    if (!state.event) return;\n    for (const row of state.allMedia.values()) {\n      if (isEligible(row) && !state.cachedPool.includes(row.id)) {\n        pushToCache(row.id);\n        if (!state.badgeShown.has(row.id)) {\n          state.priorityQueue.push(row.id);\n        }\n      }\n    }\n  }\n\n  function removeFromRotation(id) {\n    state.allMedia.delete(id);\n    const ci = state.cachedPool.indexOf(id);\n    if (ci !== -1) state.cachedPool.splice(ci, 1);\n    state.priorityQueue = state.priorityQueue.filter((x) => x !== id);\n    state.badgeShown.delete(id);\n  }\n\n  function currentWallRow() {\n    if (state.priorityQueue.length > 0) {\n      const id = state.priorityQueue.shift();\n      state.badgeShown.add(id);\n      return { row: state.allMedia.get(id), justAdded: true };\n    }\n    if (state.cachedPool.length === 0) return { row: null, justAdded: false };\n    state.rotationIndex = state.rotationIndex % state.cachedPool.length;\n    const id = state.cachedPool[state.rotationIndex];\n    state.rotationIndex++;\n    return { row: state.allMedia.get(id), justAdded: false };\n  }\n\n  function renderWall(row, justAdded) {\n    const img = document.getElementById(\"wallImg\");\n    const video = document.getElementById(\"wallVideo\");\n    const backdrop = document.getElementById(\"wallBackdrop\");\n    const badge = document.getElementById(\"justAdded\");\n    const url = window.Insphoto.mediaUrl(row.storage_path);\n\n    if (row.kind === \"video\") {\n      img.hidden = true;\n      video.hidden = false;\n      video.src = url;\n      video.currentTime = 0;\n      video.play().catch(() => {});\n      backdrop.style.backgroundImage = \"none\";\n    } else {\n      video.hidden = true;\n      video.pause();\n      img.hidden = false;\n      img.src = url;\n      backdrop.style.backgroundImage = `url(${url})`;\n    }\n\n    document.getElementById(\"wallUploader\").textContent = row.uploader_name || \"\";\n    document.getElementById(\"wallCaption\").textContent = row.caption || \"\";\n\n    if (justAdded) {\n      badge.hidden = false;\n      badge.classList.remove(\"just-added\");\n      void badge.offsetWidth;\n      badge.classList.add(\"just-added\");\n      badge.hidden = false;\n    } else {\n      badge.hidden = true;\n    }\n  }\n\n  function scheduleNextWallTick(row) {\n    clearTimeout(state.rotationTimer);\n    const ms = row && row.kind === \"video\" ? VIDEO_MAX_MS : PHOTO_MS;\n    state.rotationTimer = setTimeout(advanceWall, ms);\n  }\n\n  function advanceWall() {\n    const { row, justAdded } = currentWallRow();\n    if (!row) {\n      scheduleNextWallTick(null);\n      return;\n    }\n    renderWall(row, justAdded);\n    scheduleNextWallTick(row);\n  }\n\n  function startRotation() {\n    clearTimeout(state.rotationTimer);\n    advanceWall();\n  }\n\n  // ---------- ranking scene ----------\n\n  async function renderRanking() {\n    if (!state.event) return;\n    let rows;\n    try {\n      const { data, error } = await window.Insphoto.supabase\n        .from(\"album_media\")\n        .select(\"*\")\n        .eq(\"event_id\", state.event.id)\n        .order(\"liker_count\", { ascending: false })\n        .order(\"like_count\", { ascending: false })\n        .limit(9);\n      if (error) throw error;\n      rows = data;\n    } catch {\n      return; // keep whatever is on screen — no error UI on the LED, ever\n    }\n\n    const grid = document.getElementById(\"rankingGrid\");\n    grid.innerHTML = \"\";\n    rows.forEach((row, i) => {\n      const tile = document.createElement(\"div\");\n      tile.className = \"rank-tile\";\n      const img = document.createElement(\"img\");\n      img.src = window.Insphoto.mediaUrl(row.thumb_path || row.storage_path);\n      tile.appendChild(img);\n      const num = document.createElement(\"div\");\n      num.className = \"rank-num\";\n      num.textContent = String(i + 1);\n      tile.appendChild(num);\n      const cap = document.createElement(\"div\");\n      cap.className = \"rank-caption\";\n      cap.textContent = window.InsphotoFormat.likeLabel(row.like_count, row.liker_count);\n      tile.appendChild(cap);\n      grid.appendChild(tile);\n    });\n  }\n\n  // ---------- data loading & realtime ----------\n\n  async function loadInitialMedia() {\n    try {\n      const { data, error } = await window.Insphoto.supabase\n        .from(\"album_media\")\n        .select(\"*\")\n        .eq(\"event_id\", state.event.id)\n        .eq(\"status\", \"approved\")\n        .order(\"created_at\", { ascending: false })\n        .limit(300);\n      if (error) throw error;\n      for (const row of data) {\n        state.allMedia.set(row.id, row);\n        if (isEligible(row)) {\n          pushToCache(row.id);\n          state.badgeShown.add(row.id); // don't badge-flash the pre-existing backlog on load\n        }\n      }\n    } catch (e) {\n      console.error(e);\n    }\n  }\n\n  function clearDisconnectTimer() {\n    clearTimeout(state.disconnectTimer);\n    state.disconnectTimer = null;\n  }\n\n  function armDisconnectTimer() {\n    if (state.disconnectTimer) return;\n    state.disconnectTimer = setTimeout(() => location.reload(), FORCE_RELOAD_AFTER_DISCONNECT_MS);\n  }\n\n  function subscribe() {\n    if (state.channel) {\n      window.Insphoto.supabase.removeChannel(state.channel);\n    }\n    const channel = window.Insphoto.supabase\n      .channel(`led:${state.event.id}`)\n      .on(\n        \"postgres_changes\",\n        { event: \"INSERT\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => {\n          if (payload.new.status === \"approved\") state.allMedia.set(payload.new.id, payload.new);\n        },\n      )\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => {\n          if (payload.new.status === \"approved\") state.allMedia.set(payload.new.id, payload.new);\n          else removeFromRotation(payload.new.id);\n        },\n      )\n      .on(\n        \"postgres_changes\",\n        { event: \"DELETE\", schema: \"public\", table: \"album_media\", filter: `event_id=eq.${state.event.id}` },\n        (payload) => removeFromRotation(payload.old.id),\n      )\n      .on(\"broadcast\", { event: \"media_hidden\" }, (msg) => removeFromRotation(msg.payload.id))\n      .on(\n        \"postgres_changes\",\n        { event: \"UPDATE\", schema: \"public\", table: \"album_events\", filter: `id=eq.${state.event.id}` },\n        (payload) => {\n          state.event = payload.new;\n          applyScene();\n        },\n      )\n      .subscribe((status) => {\n        if (status === \"SUBSCRIBED\") {\n          state.reconnectAttempt = 0;\n          clearDisconnectTimer();\n        } else if ([\"TIMED_OUT\", \"CLOSED\", \"CHANNEL_ERROR\"].includes(status)) {\n          armDisconnectTimer();\n          const delay = Math.min(30000, RECONNECT_BASE_MS * 2 ** state.reconnectAttempt);\n          state.reconnectAttempt++;\n          setTimeout(subscribe, delay);\n        }\n      });\n    state.channel = channel;\n  }\n\n  function requestWakeLock() {\n    if (!(\"wakeLock\" in navigator)) return;\n    navigator.wakeLock.request(\"screen\").catch(() => {});\n    document.addEventListener(\"visibilitychange\", () => {\n      if (document.visibilityState === \"visible\") {\n        navigator.wakeLock.request(\"screen\").catch(() => {});\n      }\n    });\n  }\n\n  async function boot() {\n    state.slug = slugFromPath();\n    if (!state.slug) return;\n\n    const { data: event, error } = await window.Insphoto.supabase\n      .from(\"album_events\")\n      .select(\"*\")\n      .eq(\"slug\", state.slug)\n      .single();\n    if (error || !event) return; // silent — no dialog, just stays blank\n\n    state.event = event;\n    renderJoinCard();\n    await loadInitialMedia();\n    applyScene();\n    subscribe();\n    requestWakeLock();\n\n    state.eligibilityTimer = setInterval(recomputeEligibility, ELIGIBILITY_CHECK_MS);\n  }\n\n  document.addEventListener(\"DOMContentLoaded\", boot);\n})();\n",
  "led/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>InsPhoto LED</title>\n<link rel=\"stylesheet\" href=\"./style.css\" />\n</head>\n<body>\n  <div id=\"scene-wall\" class=\"scene active\">\n    <div id=\"wallBackdrop\" class=\"wall-backdrop\"></div>\n    <img id=\"wallImg\" class=\"wall-img\" />\n    <video id=\"wallVideo\" class=\"wall-img\" muted playsinline hidden></video>\n    <div id=\"justAdded\" class=\"just-added\" hidden>Just added</div>\n    <div class=\"wall-caption\">\n      <div id=\"wallUploader\" class=\"wall-uploader\"></div>\n      <div id=\"wallCaption\" class=\"wall-caption-text\"></div>\n    </div>\n  </div>\n\n  <div id=\"scene-ranking\" class=\"scene\">\n    <h1 class=\"ranking-title\">Ranking</h1>\n    <div id=\"rankingGrid\" class=\"ranking-grid\"></div>\n  </div>\n\n  <div id=\"scene-blank\" class=\"scene blank\"></div>\n\n  <div id=\"scene-placeholder\" class=\"scene placeholder\">\n    <p id=\"placeholderText\"></p>\n  </div>\n\n  <div id=\"joinCard\" class=\"join-card\">\n    <div id=\"joinQr\" class=\"join-qr\"></div>\n    <span>Scan to join</span>\n  </div>\n\n  <script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js\"></script>\n  <script src=\"../shared/format.js\"></script>\n  <script src=\"../shared/supabase-init.js\"></script>\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n",
  "led/style.css": "* { box-sizing: border-box; }\nhtml, body {\n  margin: 0;\n  width: 100%;\n  height: 100%;\n  background: #000;\n  overflow: hidden;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  color: #fff;\n}\n\n.scene {\n  position: fixed;\n  inset: 0;\n  display: none;\n}\n.scene.active { display: block; }\n.scene.blank { background: #000; }\n.scene.placeholder {\n  display: none;\n  align-items: center;\n  justify-content: center;\n  background: #000;\n}\n.scene.placeholder.active { display: flex; }\n.scene.placeholder p { font-size: 28px; color: #666; }\n\n/* Wall scene */\n.wall-backdrop {\n  position: absolute;\n  inset: -40px;\n  background-size: cover;\n  background-position: center;\n  filter: blur(60px) brightness(0.5) saturate(1.3);\n  transform: scale(1.1);\n}\n.wall-img {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  animation: kenburns 9s ease-in-out infinite alternate;\n}\n@keyframes kenburns {\n  from { transform: scale(1); }\n  to { transform: scale(1.06); }\n}\n.just-added {\n  position: absolute;\n  top: 36px;\n  left: 36px;\n  background: #F59E0B;\n  color: #1a1200;\n  font-weight: 800;\n  font-size: 22px;\n  padding: 10px 22px;\n  border-radius: 999px;\n  animation: fade-in-out 5s ease forwards;\n}\n@keyframes fade-in-out {\n  0% { opacity: 0; transform: translateY(-10px); }\n  10% { opacity: 1; transform: translateY(0); }\n  85% { opacity: 1; }\n  100% { opacity: 0; }\n}\n.wall-caption {\n  position: absolute;\n  left: 40px;\n  bottom: 40px;\n  max-width: 60%;\n  text-shadow: 0 2px 12px rgba(0,0,0,.8);\n}\n.wall-uploader { font-size: 30px; font-weight: 700; }\n.wall-caption-text { font-size: 22px; color: #ddd; margin-top: 6px; }\n\n/* Ranking scene */\n.ranking-title {\n  text-align: center;\n  font-size: 44px;\n  margin: 30px 0 10px;\n}\n.ranking-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 20px;\n  padding: 0 40px;\n}\n.rank-tile {\n  position: relative;\n  border-radius: 16px;\n  overflow: hidden;\n  aspect-ratio: 4/5;\n  background: #111;\n}\n.rank-tile img { width: 100%; height: 100%; object-fit: cover; display: block; }\n.rank-tile .rank-num {\n  position: absolute;\n  top: 10px; left: 10px;\n  background: #F59E0B;\n  color: #1a1200;\n  font-weight: 800;\n  font-size: 26px;\n  width: 44px; height: 44px;\n  border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n}\n.rank-tile .rank-caption {\n  position: absolute; left: 0; right: 0; bottom: 0;\n  padding: 30px 12px 10px;\n  font-size: 28px;\n  font-weight: 700;\n  background: linear-gradient(to top, rgba(0,0,0,.85), transparent);\n}\n\n/* Always-visible join card */\n.join-card {\n  position: fixed;\n  right: 30px;\n  bottom: 30px;\n  background: rgba(0,0,0,.55);\n  border-radius: 16px;\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  z-index: 30;\n  font-size: 20px;\n  font-weight: 700;\n}\n.join-qr { background: #fff; padding: 8px; border-radius: 10px; }\n",
  "shared/device.js": "// device_id: a UUID in localStorage, created on first visit. Not a security\n// boundary (PRD §6.5) — used only for like attribution, \"my photos\", and\n// self-delete matching.\n(function () {\n  const KEY = \"insphoto_device_id\";\n  const NAME_KEY = \"insphoto_name\";\n\n  function uuid() {\n    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();\n    return \"xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx\".replace(/[xy]/g, (c) => {\n      const r = (Math.random() * 16) | 0;\n      const v = c === \"x\" ? r : (r & 0x3) | 0x8;\n      return v.toString(16);\n    });\n  }\n\n  function deviceId() {\n    let id = localStorage.getItem(KEY);\n    if (!id) {\n      id = uuid();\n      localStorage.setItem(KEY, id);\n    }\n    return id;\n  }\n\n  function guestName(next) {\n    if (next !== undefined) {\n      localStorage.setItem(NAME_KEY, next);\n      return next;\n    }\n    return localStorage.getItem(NAME_KEY) || \"\";\n  }\n\n  window.InsphotoDevice = { deviceId, guestName };\n})();\n",
  "shared/format.js": "(function () {\n  function compactNumber(n) {\n    if (n < 1000) return String(n);\n    if (n < 1_000_000) return (n / 1000).toFixed(n < 10000 ? 1 : 0) + \"k\";\n    return (n / 1_000_000).toFixed(1) + \"m\";\n  }\n\n  function relativeTime(iso) {\n    const then = new Date(iso).getTime();\n    const diffSec = Math.max(0, (Date.now() - then) / 1000);\n    if (diffSec < 60) return \"just now\";\n    if (diffSec < 3600) return `${Math.floor(diffSec / 60)}m ago`;\n    if (diffSec < 86400) return `${Math.floor(diffSec / 3600)}h ago`;\n    return `${Math.floor(diffSec / 86400)}d ago`;\n  }\n\n  function likeLabel(likeCount, likerCount) {\n    return `❤️ ${compactNumber(likeCount)} · ${compactNumber(likerCount)} people`;\n  }\n\n  function bytesLabel(bytes) {\n    if (bytes < 1024) return `${bytes} B`;\n    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;\n    if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(2)} MB`;\n    return `${(bytes / 1024 / 1024 / 1024).toFixed(2)} GB`;\n  }\n\n  window.InsphotoFormat = { compactNumber, relativeTime, likeLabel, bytesLabel };\n})();\n",
  "shared/supabase-init.js": "// Loaded after the supabase-js UMD CDN script. Anon key + URLs here are\n// public/publishable by design (PRD §4) — nothing secret lives client-side.\n(function () {\n  const SUPABASE_URL = \"https://pqhstyhtakohvwfjpmmf.supabase.co\";\n  const ANON_KEY = \"sb_publishable_EEzW55bkKAsvOLznhe6j5g_We-O-p8u\";\n  const R2_PUBLIC_BASE = \"https://cdn.insphoto.my\";\n\n  const client = window.supabase.createClient(SUPABASE_URL, ANON_KEY, {\n    realtime: { params: { eventsPerSecond: 10 } },\n  });\n\n  // Requests to /e/:slug, /h/:slug, /s/:slug may be served either at the\n  // project's default functions path (/functions/v1/album/...) or from a\n  // custom domain mounted at the function root. Work out the right prefix\n  // for same-origin API calls either way.\n  function functionRoot() {\n    const marker = \"/album\";\n    const idx = location.pathname.indexOf(marker);\n    if (idx === -1) return \"\";\n    return location.pathname.slice(0, idx + marker.length);\n  }\n\n  function mediaUrl(key) {\n    if (!key) return null;\n    return `${R2_PUBLIC_BASE}/${key}`;\n  }\n\n  window.Insphoto = {\n    supabase: client,\n    apiPath: (p) => functionRoot() + p,\n    mediaUrl,\n  };\n})();\n",
};
